import { Book } from "@/lib/types";

export const _1samuel: Book = {
  id: "1samuel",
  name: "1. Samuel",
  shortName: "1Sam",
  testament: "old",
  introduction: `Gott erweckt einen König in Israel\nIn den ältesten hebräischen Handschriften sind die beiden Samuelbücher nicht getrennt. Erst die im 3. Jahrhundert v.Chr. entstandene griechische Übersetzung des Alten Testaments (Septuaginta) nahm die Teilung vor, die seitdem in allen Bibelausgaben (auch den hebräischen) beibehalten wurde.\n**Das erste Buch Samuel** beschreibt einen Zeitraum von ungefähr 100 Jahren. Es beginnt mit der Geburt Samuels (um 1120 v.Chr.) und beschreibt die geschichtlichen Ereignisse des beginnenden Königtums in Israel. Nach 1. Chronik 29,29 hat Samuel wenigstens einen Teil des Buches geschrieben. Der eigentliche Verfasser ist uns aber unbekannt. Er müsste mindestens noch im Jahr 931 v.Chr. gelebt haben, als Israel sich in Nord- und Südreich teilte, was 1. Samuel 27,6 durch die Erwähnung der Könige von Juda (nicht Israel) angedeutet ist. Samuel ist die zentrale Gestalt in den ersten Kapiteln. Er hat die Aufgabe, die weiteren Hauptpersonen Saul und David auf ihren Dienst vorzubereiten.\n****Wie Israel zu einem König kommt, der aber Gott ungehorsam ist und den von Gott bestimmten künftigen König verfolgt.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Der Mann stammte aus dem Rama* der Zufiten im Gebirge Efraïm* und hieß Elkana Ben-Jerocham. Er war ein Enkel Elihus und Urenkel von Tohu, dem Sohn des Efraïmiters Zuf.", heading: "1-8: Samuel, der letzte Richter\nEine Frau betet um einen Sohn", footnotes: ["Rama, eigentlich: Ramatajim (= Doppel-Rama). Es gab sechs verschiedene Orte, die Rama (= Höhe) genannt wurden.", "Das Gebirge Efraïm war die zentrale Bergkette des Westjordanlandes."] },
      { number: 2, text: "Elkana hatte zwei Frauen, Hanna und Peninna. Peninna hatte Kinder, doch Hanna war kinderlos." },
      { number: 3, text: "Einmal im Jahr ging Elkana nach Schilo hinauf, um Jahwe anzubeten und ihm ein Opfer zu bringen. Als Priester Jahwes wirkten die beiden Söhne Elis, Hofni und Pinhas, dort." },
      { number: 4, text: "Beim Opfermahl gab Elkana seiner Frau Peninna und ihren Söhnen und Töchtern immer die Anteile, die ihnen zukamen," },
      { number: 5, text: "Hanna jedoch gab er einen doppelten Anteil, denn er liebte sie. Doch Jahwe hatte ihr eigene Kinder versagt." },
      { number: 6, text: "Ihre Rivalin kränkte sie schwer und demütigte sie wegen ihrer Kinderlosigkeit." },
      { number: 7, text: "Das wiederholte sich jedes Jahr. Immer wenn sie zum Haus Jahwes hinaufzogen, kränkte sie sie derartig, dass sie weinte und nichts aß." },
      { number: 8, text: "Elkana, ihr Mann, sagte dann zu ihr: \"Hanna, warum weinst du denn? Warum isst du nichts? Warum bist du so traurig? Bin ich dir nicht mehr wert als zehn Söhne?\"" },
      { number: 9, text: "Eines Tages jedoch stand Hanna nach dem Opfermahl in Schilo auf. Der Priester Eli saß auf einem Stuhl neben dem Eingang zum Heiligtum Jahwes." },
      { number: 10, text: "Hanna war im Innersten verbittert. Sie betete zu Jahwe und weinte sehr." },
      { number: 11, text: "Dabei legte sie ein Gelübde ab und sagte: \"Jahwe, du Allmächtiger! Sieh doch das Elend deiner Dienerin an, denk an mich und vergiss mich nicht! Wenn du mir einen Sohn schenkst, dann soll er sein Leben lang dir, Jahwe, gehören. Und niemals soll sein Haar geschnitten werden.\"" },
      { number: 12, text: "Sie betete auf diese Weise lange vor Jahwe, und Eli beobachtete sie. Er sah, wie sich ihre Lippen bewegten," },
      { number: 13, text: "konnte aber nichts hören, weil sie still für sich betete. Darum hielt er sie für betrunken" },
      { number: 14, text: "und fuhr sie an: \"Wie lange willst du dich hier als Betrunkene aufführen? Sieh zu, dass du deinen Rausch loswirst!\"" },
      { number: 15, text: "\"Nein, mein Herr\", erwiderte Hanna. \"Ich bin nicht betrunken, ich bin nur eine unglückliche Frau und habe Jahwe mein Herz ausgeschüttet." },
      { number: 16, text: "Denk nicht so schlecht von deiner Dienerin. Denn aus großem Kummer und lauter Verzweiflung habe ich so lange gebetet.\"" },
      { number: 17, text: "Da erwiderte Eli: \"Geh in Frieden! Der Gott Israels wird deine Bitte erfüllen.\"" },
      { number: 18, text: "Sie sagte: \"Lass deine Dienerin Gnade vor dir finden!\" Dann ging sie ihres Weges. Sie aß wieder und sah nicht mehr so traurig aus." },
      { number: 19, text: "Früh am nächsten Morgen brachen sie auf, beteten noch einmal vor Jahwe und kehrten in ihr Haus nach Rama zurück. Als Elkana das nächste Mal mit ihr schlief, erhörte Jahwe ihr Gebet." },
      { number: 20, text: "Sie wurde schwanger und bekam einen Sohn. \"Ich habe ihn von Jahwe erbeten\", sagte sie und nannte ihn Samuel*.", footnotes: ["Samuel klingt im Hebräischen wie \"von Gott erhört\"."] },
      { number: 21, text: "Als dann Elkana mit seiner ganzen Familie wieder hinaufzog, um Jahwe das jährliche Opfer und die Gaben, die er ihm versprochen hatte, zu bringen," },
      { number: 22, text: "reiste Hanna nicht mit. \"Ich werde den Jungen erst zu Jahwe bringen, wenn ich ihn abgestillt habe\", sagte sie zu ihrem Mann. \"Dann soll er für immer dort bleiben.\"" },
      { number: 23, text: "Elkana sagte zu ihr: \"Tu, was du für richtig hältst. Bleib zu Hause, bis du ihn entwöhnt hast. Möge Jahwe dann auch sein Wort wahr machen.\" So blieb die Frau zu Hause und versorgte ihren Sohn." },
      { number: 24, text: "Als sie ihn abgestillt hatte, brachte sie ihn ins Haus Jahwes nach Schilo, dazu einen dreijährigen Stier, einen kleinen Sack* Mehl und einen Schlauch Wein. Das Kind war aber noch sehr jung.", footnotes: ["kleinen Sack. Wörtlich: ein Efa = 12 Kilogramm."] },
      { number: 25, text: "Sie schlachteten den Stier und brachten den Jungen zu Eli." },
      { number: 26, text: "Hanna sagte: \"Verzeihung, mein Herr! So wahr du lebst, mein Herr, ich bin die Frau, die hier bei dir stand, um zu Jahwe zu beten." },
      { number: 27, text: "Hier ist das Kind, um das ich damals gebetet habe. Jahwe hat mein Gebet erhört; er gab mir, worum ich ihn bat." },
      { number: 28, text: "So will auch ich mein Versprechen erfüllen und übergebe ihn Jahwe. Sein Leben lang soll er Jahwe gehören.\" Dann warfen sie sich zum Gebet vor Jahwe nieder." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Hanna betete:Jahwe hat mich wieder fröhlich gemacht, / er hat mich aufgerichtet und gestärkt. / Jetzt kann ich meine Feinde verspotten, / denn deine Hilfe machte mich froh.", heading: "Hannas Loblied" },
      { number: 2, text: "Jahwe allein ist heilig, / ja keiner außer dir, / keiner ist ein Fels wie unser Gott." },
      { number: 3, text: "Spielt euch doch nicht so auf, / tut nicht so groß, / prahlt nicht so frech! / Denn Jahwe ist ein Gott, der alles weiß, / vor ihm werden die Taten gewogen." },
      { number: 4, text: "Die Bogen der Helden zerbrechen, / doch die Schwachen gürten sich mit Kraft." },
      { number: 5, text: "Die Satten arbeiten jetzt für ihr Brot, / und die Hungrigen ruhen sich aus. / Die kinderlose Frau bringt sieben Kinder zur Welt, / die kinderreiche welkt dahin." },
      { number: 6, text: "Jahwe tötet und macht lebendig, / schickt zu den Toten und holt wieder zurück." },
      { number: 7, text: "Jahwe macht arm und macht reich, / er erniedrigt und erhöht." },
      { number: 8, text: "Er hebt den Geringen aus dem Staub, / holt den Armen aus dem Schmutz, / um ihn unter die Edlen zu setzen, / den Thron der Ehre lässt er sie erben.Die Fundamente der Welt gehören Jahwe, / auf sie hat er den Erdkreis gegründet." },
      { number: 9, text: "Er behütet die Schritte seiner Frommen, / doch die Frevler enden im Dunkel, / denn niemand ist stark durch die eigene Kraft." },
      { number: 10, text: "Die mit Jahwe streiten, zerbrechen. / Über sie donnert er im Himmel. / Über die ganze Erde hält Jahwe Gericht. / Seinem König verleiht er Macht, / er stärkt und erhöht seinen Gesalbten*.", footnotes: ["Gesalbter. Hebräisch: Messias; Griechisch: Christus. Hier und in V. 35 wird zum ersten Mal in der Bibel der kommende König als Gesalbter bezeichnet."] },
      { number: 11, text: "Elkana kehrte nach Rama in sein Haus zurück. Der Junge aber diente Jahwe unter der Aufsicht des Priesters Eli.", heading: "Missstände am Heiligtum" },
      { number: 12, text: "Elis Söhne aber waren boshafte Männer. Sie kannten Jahwe nicht." },
      { number: 13, text: "Die Priester hatten es sich zur Gewohnheit gemacht, ihre Diener zu jedem aus dem Volk zu schicken, der ein Schlachtopfer brachte. Während das Fleisch für das Opfermahl noch kochte, kam der Diener mit einer dreizinkigen Gabel in der Hand" },
      { number: 14, text: "und stieß damit in den Tiegel, den Kessel, die Pfanne oder den Topf. Und alles, was er mit der Gabel herauszog, nahm er den Leuten weg. So machten sie es mit allen Israeliten, die nach Schilo kamen." },
      { number: 15, text: "Jetzt kamen sie sogar schon, bevor man das Fett auf dem Altar verbrannt hatte, und sagten zu dem Opfernden: \"Gib Fleisch zum Braten für den Priester! Er will kein gekochtes Fleisch von dir nehmen, sondern nur rohes.\"" },
      { number: 16, text: "Wenn der Mann entgegnete: \"Man muss doch erst das Fett zum Rauchopfer verbrennen; dann kannst du dir nehmen, was du willst\", erwiderte der Diener: \"Nein, sofort gibst du es her, sonst nehme ich es mit Gewalt!\"" },
      { number: 17, text: "Die Schuld der jungen Männer wog schwer vor Jahwe, denn sie verachteten die Opfer, die ihm gebracht wurden." },
      { number: 18, text: "Samuel aber tat seinen Dienst vor Jahwe, ein Knabe, der ein leinenes Efod* trug.", footnotes: ["Das Efod aus Leinen war offenbar ein ärmelloses Gewand und gehörte zur Dienstkleidung eines Priesters, muss aber von dem Efod des Hohenpriesters (2. Mose 39) unterschieden werden, das aus anderem Material hergestellt wurde."] },
      { number: 19, text: "Seine Mutter machte ihm jedes Jahr ein kleines Obergewand und brachte es mit, wenn sie mit ihrem Mann zum jährlichen Opferfest hinaufzog." },
      { number: 20, text: "Eli segnete Elkana und seine Frau: \"Jahwe gebe dir noch andere Kinder von dieser Frau\", sagte er, \"anstelle des einen, den sie von Jahwe erbeten hat!\" Dann gingen sie nach Hause zurück." },
      { number: 21, text: "Jahwe nahm sich Hannas an. Sie wurde noch mehrmals schwanger und bekam noch drei Söhne und zwei Töchter. Samuel aber wuchs bei Jahwe auf." },
      { number: 22, text: "Eli war sehr alt geworden. Als er hörte, was seine Söhne den Israeliten antaten und dass sie mit den Frauen schliefen, die sich am Eingang zum Zelt* der Gottesbegegnung zusammenscharten*,", footnotes: ["Eingang zum Zelt meint hier wie auch an einigen anderen Stellen nicht den Eingang zum Heiligtum, sondern den Platz vor dem Eingang zum Vorhof, wo sich auch das ganze Volk versammeln konnte (3. Mose 8,3; 4. Mose 10,3; 25,6).", "Frauen … zusammenscharten. Das Verb bedeutet eigentlich: kämpfen gegen, in den Krieg ziehen. Was diese Frauen, die auch in 2. Mose 38,8 erwähnt werden, wirklich taten, ist unbekannt."] },
      { number: 23, text: "sagte er zu ihnen: \"Warum tut ihr so etwas? Warum muss ich von allen Leuten so schlimme Dinge über euch hören?" },
      { number: 24, text: "Hört auf damit, meine Söhne! Es ist nicht gut, was man im Volk Jahwes über euch verbreitet." },
      { number: 25, text: "Wenn jemand gegen einen Menschen sündigt, wird Gott über ihn entscheiden. Wenn aber jemand gegen Jahwe sündigt, wer soll dann noch für ihn eintreten?\" Doch sie hörten nicht auf ihren Vater, denn Jahwe war entschlossen, sie zu töten." },
      { number: 26, text: "Samuel aber wuchs zu einem jungen Mann heran, der Gott und den Menschen gefiel." },
      { number: 27, text: "Eines Tages kam ein Gottesmann zu Eli und sagte: \"So spricht Jahwe: Habe ich mich deinen Vorfahren nicht deutlich offenbart, als sie noch Sklaven des Pharao in Ägypten waren?", heading: "Gerichtsankündigung für Elis Familie" },
      { number: 28, text: "Sie habe ich mir aus allen Stämmen Israels zum Priesterdienst erwählt. Sie sollten auf meinem Altar Räucheropfer bringen, und sie sollten das Efod vor mir tragen. Deiner Sippe habe ich das Recht auf einen Anteil an allen Feueropfern der Israeliten gegeben." },
      { number: 29, text: "Warum verachtet ihr meine Schlacht- und Speisopfer so? Sie sollen doch nach meinem Befehl in meine Wohnung gebracht werden. Du ehrst deine Söhne mehr als mich, Eli, und lässt es geschehen, dass ihr euch von den Erstlingsgaben* meines Volkes Israel mästet.", footnotes: ["Erstlingsgaben. Das Erlesenste und Beste einer Sache, das Gott geopfert wurde, bevor der Rest für den eigenen Gebrauch verwendet werden durfte; vergleiche 4. Mose 15,18-21. Dadurch wurde das Ganze geheiligt."] },
      { number: 30, text: "Darum lautet der Spruch Jahwes folgendermaßen:Ich hatte allerdings zugesagt, dass deine Familie und die deiner Vorfahren immer vor mir sein dürfen. Aber nun sage ich, Jahwe: Das wird auf keinen Fall geschehen! Denn die mich ehren, ehre auch ich, und die mich verachten, gebe ich der Verachtung preis." },
      { number: 31, text: "Pass auf! Die Zeit wird kommen, da werde ich deine Lebenskraft brechen und die deiner Nachkommen, sodass es in deiner Familie keinen alten Mann mehr gibt." },
      { number: 32, text: "Du wirst den Feind in der Wohnung Gottes erblicken, obwohl Jahwe Israel Gutes tun wird. Aber in deiner Familie wird es niemand mehr zu Alter und Ansehen bringen." },
      { number: 33, text: "Ich werde zwar nicht jeden deiner Nachkommen, der am Altar stehen darf, beseitigen, denn sonst würdest du vor Kummer und Schmerz vergehen, aber die große Mehrzahl deiner Familie soll im besten Mannesalter sterben." },
      { number: 34, text: "Zum Zeichen wird dir das sein, was über deine beiden Söhne Hofni und Pinhas kommt: Beide werden am gleichen Tag sterben." },
      { number: 35, text: "Dann werde ich einen Priester berufen, der mir treu bleibt, der mir dient und tut, was mir gefällt. Ihm werde ich eine beständige Nachkommenschaft schenken, und er wird immer bei meinem Gesalbten sein." },
      { number: 36, text: "Jeder, der dann von deiner Familie noch lebt, wird zu diesem Priester kommen und auf den Knien um etwas Geld und Brot betteln. 'Bitte lass mich doch beim Priesterdienst helfen', wird er sagen, 'damit ich wenigstens etwas zu essen habe!'\"" },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Der junge Samuel diente Jahwe unter Aufsicht des Priesters Eli. Damals waren Worte Jahwes und Visionen selten.", heading: "Samuels Berufung" },
      { number: 2, text: "Eines Nachts geschah es: Eli schlief an seinem gewohnten Platz. Er war schon fast erblindet." },
      { number: 3, text: "Samuel schlief im Heiligtum, wo sich auch die Bundeslade befand. Die Lampe Gottes brannte noch," },
      { number: 4, text: "als Jahwe rief: \"Samuel!\" – \"Ja\", antwortete er" },
      { number: 5, text: "und lief zu Eli. \"Hier bin ich! Du hast mich gerufen!\" – \"Nein\", sagte Eli, \"ich habe dich nicht gerufen. Leg dich wieder hin!\" Samuel tat es." },
      { number: 6, text: "Jahwe rief noch einmal: \"Samuel!\" Wieder stand Samuel auf, ging zu Eli und sagte: \"Hier bin ich! Du hast mich gerufen!\" – \"Nein\", sagte Eli, \"ich habe dich nicht gerufen, mein Sohn. Leg dich wieder hin!\"" },
      { number: 7, text: "Samuel hatte Jahwe noch nicht kennengelernt und seine Stimme noch nie gehört." },
      { number: 8, text: "Dann rief Jahwe ihn zum dritten Mal. Wieder stand Samuel auf, ging zu Eli und sagte: \"Hier bin ich! Du hast mich gerufen!\" Da merkte Eli, dass Jahwe den Jungen rief." },
      { number: 9, text: "Er sagte zu Samuel: \"Leg dich wieder hin! Und wenn du noch einmal gerufen wirst, dann sag: 'Sprich, Jahwe, dein Diener hört.'\"" },
      { number: 10, text: "Da trat Jahwe an Samuel heran und rief wie vorher: \"Samuel, Samuel!\" Der Junge erwiderte: \"Sprich, dein Diener hört!\"" },
      { number: 11, text: "Da sagte Jahwe zu ihm: \"Pass auf! Ich werde in Israel etwas tun, dass es jedem, der davon hört, in den Ohren dröhnt." },
      { number: 12, text: "Ich werde alles eintreffen lassen, was ich Eli und seiner Familie angedroht habe." },
      { number: 13, text: "Ich habe ihm angekündigt, dass ich seine Familie immer bestrafen werde. Denn er wusste, dass seine Söhne den Fluch über sich brachten, aber er hat sie nicht daran gehindert." },
      { number: 14, text: "Darum habe ich Elis Familie geschworen: Kein Schlacht- oder Speisopfer kann diese Schuld jemals sühnen!\"" },
      { number: 15, text: "Bis zum Morgen blieb Samuel auf seinem Lager. Dann öffnete er die Türen des Hauses Jahwes. Doch er fürchtete sich, Eli von der Erscheinung zu berichten." },
      { number: 16, text: "Da rief Eli: \"Samuel, mein Sohn!\" – \"Hier bin ich\", erwiderte Samuel." },
      { number: 17, text: "\"Was hat er dir gesagt? Verschweige mir ja nichts! Gottes Zorn soll dich treffen, wenn du mir etwas von dem verschweigst, was er dir gesagt hat!\"" },
      { number: 18, text: "Da teilte ihm Samuel alles mit. Er verschwieg nichts. Eli aber sagte: \"Er ist Jahwe. Er soll tun, was er für richtig hält.\"" },
      { number: 19, text: "Samuel wuchs heran. Jahwe stand ihm bei und ließ alles in Erfüllung gehen, was er durch Samuel sagen ließ." },
      { number: 20, text: "Ganz Israel von Dan bis Beerscheba* erkannte, dass Jahwe ihn zu seinem Propheten bestimmt hatte.", footnotes: ["Dan bis Beerscheba. Das meint ganz Israel vom nördlichsten bis zum südlichsten Ort."] },
      { number: 21, text: "Jahwe offenbarte sich Samuel auch weiterhin in Schilo und ließ sein Wort zu ihm kommen." },
    ] },
    { number: 4, verses: [
      { number: 1, text: "In ganz Israel hörte man auf Samuel. Wieder einmal mussten die Israeliten gegen die Philister in den Krieg ziehen. Bei Eben-Eser* schlugen sie ihr Feldlager auf. Die Philister standen bei Afek*", heading: "Der Verlust der Bundeslade", footnotes: ["Eben-Eser. Der Ort lag wahrscheinlich 21 Kilometer östlich von Joppe.", "Das Afek in der Scharon-Ebene lag 18 km östlich von Joppe."] },
      { number: 2, text: "und griffen an. Nach einem langen, erbitterten Kampf gewannen sie die Oberhand. Israel wurde geschlagen und verlor auf dem Schlachtfeld etwa 4000 Mann." },
      { number: 3, text: "Als das Heer ins Lager zurückkam, fragten sich die Ältesten Israels: \"Warum hat Jahwe zugelassen, dass die Philister uns heute besiegt haben? Lasst uns die Bundeslade aus Schilo holen! Dann wird Jahwe unter uns sein und uns aus der Gewalt unserer Feinde retten.\"" },
      { number: 4, text: "Sie schickten einige Männer nach Schilo und ließen die Lade holen, die Lade des Bundes mit Jahwe, der über den Cherubim* thront. Die beiden Söhne Elis, Hofni und Pinhas, begleiteten die Bundeslade Gottes.", footnotes: ["Cherub, Mehrzahl: Cherubim. Majestätisches (Engel-)Wesen, das Gottes Herrlichkeit repräsentiert."] },
      { number: 5, text: "Als die Lade Jahwes ins Lager kam, brach unter den Israeliten ein Jubelsturm los, dass die Erde dröhnte." },
      { number: 6, text: "Die Philister hörten den Lärm und riefen: \"Was ist das für ein lauter Jubel im Lager der Hebräer*?\" Als sie herausfanden, dass die Lade Jahwes im Lager Israels angekommen war,", footnotes: ["Hebräer. In der Bibel wird der Begriff meist von Nichtisraeliten als herabsetzende Bezeichnung für die Nachkommen Abrahams gebraucht."] },
      { number: 7, text: "bekamen sie Angst. \"Gott ist ins Lager gekommen\", sagten sie. \"Weh uns! Das hat es noch nie gegeben!" },
      { number: 8, text: "Weh uns! Wer wird uns vor solch einem mächtigen Gott retten? Das ist der Gott, der den Ägyptern in der Wüste einen Schlag nach dem anderen versetzt hat." },
      { number: 9, text: "Auf, ihr Philister, macht euch stark und seid Männer! Sonst müsst ihr den Hebräern dienen, wie sie euch gedient haben. Zeigt, dass ihr Männer seid, und kämpft!\"" },
      { number: 10, text: "Da kämpften die Philister, und Israel erlitt eine vernichtende Niederlage. Das Heer löste sich auf, und jeder floh nach Hause. 30.000 Mann blieben tot auf dem Schlachtfeld." },
      { number: 11, text: "Die Philister erbeuteten auch die Lade Gottes, und Hofni und Pinhas, die beiden Söhne Elis, fanden dabei den Tod." },
      { number: 12, text: "Ein Mann aus dem Stamm Benjamin lief vom Schlachtfeld weg und kam noch am selben Tag nach Schilo. Seine Kleidung war zerrissen und er hatte Erde auf dem Kopf.*", heading: "Elis Tod", footnotes: ["Kleider ... Kopf. Das waren Zeichen von Trauer und Entsetzen."] },
      { number: 13, text: "Als er ankam, saß Eli auf einem Stuhl neben der Straße und hielt Ausschau, denn er hatte Angst um die Lade Gottes. Als der Bote in die Stadt kam und berichtete, schrie die ganze Stadt auf." },
      { number: 14, text: "Eli hörte das laute Schreien und fragte: \"Was ist das für ein großer Lärm?\" Da eilte der Bote zu ihm, um zu berichten." },
      { number: 15, text: "Eli war inzwischen 98 Jahre alt und seine Augen waren starr geworden. Er konnte nichts mehr sehen." },
      { number: 16, text: "Der Mann sagte: \"Ich komme vom Schlachtfeld und bin heute von dort geflohen.\" – \"Wie ist es ausgegangen, mein Sohn?\", fragte Eli." },
      { number: 17, text: "\"Israel ist vor den Philistern geflohen\", erwiderte der Bote. \"Es hat eine große Niederlage gegeben. Deine beiden Söhne Hofni und Pinhas sind tot. Die Lade Gottes ist erbeutet worden.\"" },
      { number: 18, text: "Als er die Lade Gottes erwähnte, fiel Eli rückwärts von seinem Stuhl an der Seite des Tores. Dabei brach er sich das Genick und starb, denn er war ein alter und schwerer Mann. 40 Jahre lang war er Israels Richter gewesen." },
      { number: 19, text: "Seine Schwiegertochter, die Frau des Pinhas, war hochschwanger. Als sie die Nachricht hörte, dass die Lade Gottes erbeutet worden war und dass ihr Schwiegervater und ihr Mann tot waren, brach sie zusammen. Die Wehen hatten sie überfallen und es kam zur Geburt." },
      { number: 20, text: "Als sie schon im Sterben lag, sagten die Frauen, die um sie herumstanden: \"Hab keine Angst! Du hast einen Sohn geboren.\" Aber sie gab keine Antwort und lag völlig teilnahmslos da." },
      { number: 21, text: "Sie nannte nur den Namen des Jungen: Ikabod*. Dabei dachte sie an den Verlust der Lade Gottes und den Tod ihres Schwiegervaters und ihres Mannes", footnotes: ["Ikabod bedeutet etwa: \"Wo ist die Herrlichkeit?\""] },
      { number: 22, text: "und sagte: \"Die Herrlichkeit Gottes ist aus Israel fort, denn die Lade Gottes ist verloren!\"" },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Die Philister brachten die erbeutete Lade Gottes von Eben-Eser nach Aschdod*", heading: "Die Bundeslade bei den Philistern", footnotes: ["Aschdod. Bedeutende Philisterstadt, 35 km südlich von Joppe, 5 km vom Mittelmeer entfernt."] },
      { number: 2, text: "in den Tempel ihres Gottes Dagon* und stellten sie neben dessen Standbild auf.", footnotes: ["Dagon. Im Götterglauben der Kanaanäer galt Dagon als der Vater von Baal. Er wurde als Wetter- und besonders als Getreidegott (dagan = Getreide) in Tempeln der Philisterstädte Gaza, Aschdod und Bet-Schean verehrt."] },
      { number: 3, text: "Als die Einwohner Aschdods am nächsten Morgen in den Tempel kamen, war Dagon auf einmal umgestürzt und lag mit dem Gesicht zur Erde vor der Lade Jahwes. Sie nahmen sich seiner an und stellten ihn wieder an seinen Platz." },
      { number: 4, text: "Doch am nächsten Morgen lag Dagon wieder vor der Lade Jahwes am Boden. Aber nur sein Rumpf war übrig geblieben. Sein Kopf und seine Hände waren abgehauen und lagen auf der Schwelle." },
      { number: 5, text: "Deshalb tritt bis heute kein Priester Dagons und kein Besucher des Tempels auf die Türschwelle." },
      { number: 6, text: "Die Leute von Aschdod bekamen die Macht Jahwes zu spüren. Er schlug die Bewohner der ganzen Umgebung mit schmerzhaften Beulen." },
      { number: 7, text: "Da sagten sie: \"Die Lade des Gottes Israels muss fort! Seine Hand liegt zu schwer auf uns und Dagon, unserem Gott.\"" },
      { number: 8, text: "Sie riefen alle Philisterfürsten zusammen und berieten, was sie mit der Lade des Gottes Israels machen sollten. \"Bringen wir sie nach Gat*!\", entschieden sie; und so wurde die Lade dorthin gebracht.", footnotes: ["Gat. Bedeutendste der fünf Philisterstädte, 40 km südlich von Joppe. Sie hatte einen König und war die spätere Heimatstadt des Goliat."] },
      { number: 9, text: "Aber nachdem sie dort angekommen war, legte Jahwe seine Hand auch auf diese Stadt. Es entstand eine große Panik, denn er ließ bei allen Leuten, klein und groß, schmerzhafte Beulen aufbrechen." },
      { number: 10, text: "Da schickten sie die Lade Gottes nach Ekron. Als sie dort ankam, schrien die Einwohner von Ekron um Hilfe. \"Jetzt haben sie die Lade des Gottes Israels zu uns gebracht!\", riefen sie. \"Sie werden uns noch alle umbringen!\"" },
      { number: 11, text: "Sie riefen die Philisterfürsten zusammen und sagten: \"Schickt die Lade des Gottes Israels dahin zurück, woher sie gekommen ist, damit sie nicht unser ganzes Volk umbringt!\" Denn die Hand Gottes lastete schwer auf ihnen und versetzte die ganze Stadt in Todesangst." },
      { number: 12, text: "Die Leute, die nicht starben, waren mit Beulen bedeckt. Der Notschrei der Stadt stieg zum Himmel auf." },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Sieben Monate lang war die Lade Jahwes im Gebiet der Philister.", heading: "Die Bundeslade kommt zurück" },
      { number: 2, text: "Schließlich riefen die Philister ihre Priester und Wahrsager und fragten sie: \"Was sollen wir mit der Lade Jahwes machen? Sagt uns, auf welche Art und Weise wir sie an ihren Ort zurückschicken sollen.\"" },
      { number: 3, text: "Sie sagten: \"Wenn ihr die Lade des Gottes Israels zurückschickt, dann müsst ihr ihm auf jeden Fall ein Versöhnungsgeschenk dazutun. Dann werdet ihr wieder gesund und erfahrt auch, warum seine Hand nicht von euch lässt.\"" },
      { number: 4, text: "\"Was für ein Versöhnungsgeschenk sollen wir ihm schicken?\", fragten sie. Die Antwort lautete: \"Schickt für jeden der fünf Fürsten der Philister eine Beule und eine Maus aus Gold. Denn alle fünf Fürstentümer waren von der Plage betroffen." },
      { number: 5, text: "Macht also Nachbildungen von euren Beulen und den Mäusen, die euch das Land zugrunde gerichtet haben. Ehrt den Gott Israels damit! Vielleicht wird er dann den Druck, der auf euch, eurem Gott und eurem Land liegt, zurücknehmen." },
      { number: 6, text: "Warum wollt ihr so starrsinnig sein wie die Ägypter und ihr Pharao? Als Jahwe ihnen damals übel mitgespielt hatte, hielten sie die Israeliten nicht mehr zurück und ließen sie ziehen." },
      { number: 7, text: "Schafft jetzt einen neuen Wagen herbei und spannt zwei Kühe davor, Muttertiere, auf denen noch nie ein Joch gelegen hat. Nehmt ihnen aber die Kälber weg und bringt sie in den Stall zurück." },
      { number: 8, text: "Stellt dann die Lade Jahwes auf den Wagen. Die goldenen Gegenstände, die ihr ihm als Versöhnungsgeschenk zuwendet, legt in ein Kästchen und stellt es daneben. Lasst dann die Kühe laufen, wohin sie wollen." },
      { number: 9, text: "Dann werdet ihr es sehen: Wenn sie den Weg hinauf nach Bet-Schemesch* wählen, dann hat er uns diese Plage geschickt. Wenn sie eine andere Richtung nehmen, dann sehen wir, dass nicht er uns geschlagen hat. Dann hat die Plage uns zufällig getroffen.\"", footnotes: ["Bet-Schemesch liegt 24 km westlich von Jerusalem."] },
      { number: 10, text: "Genauso machten es die Männer: Sie nahmen zwei säugende Kühe, spannten sie vor den Wagen und sperrten ihre Kälber im Stall ein." },
      { number: 11, text: "Dann stellten sie die Lade Jahwes auf den Wagen und dazu das Kästchen mit den goldenen Mäusen und den Nachbildungen ihrer Beulen aus Gold." },
      { number: 12, text: "Die Kühe schlugen genau den Weg nach Bet-Schemesch ein und gingen geradeaus auf ihm weiter. Dabei brüllten sie fortwährend, wichen aber weder rechts noch links vom Weg ab. Die Fürsten der Philister folgten ihnen bis zum Gebiet von Bet-Schemesch." },
      { number: 13, text: "Die Leute von Bet-Schemesch waren gerade bei der Weizenernte im Tal. Als sie aufblickten, sahen sie die Bundeslade herankommen und freuten sich." },
      { number: 14, text: "Auf einem Feldstück, das einem gewissen Joschua aus Bet-Schemesch gehörte, blieb der Wagen neben einem großen Felsblock stehen. Da spalteten sie das Holz des Wagens und schlachteten die Kühe zum Brandopfer für Jahwe." },
      { number: 15, text: "Vorher hatten Leviten die Lade Jahwes und das Kästchen mit den goldenen Gegenständen vom Wagen genommen und beides auf den Felsen gestellt. Die Männer von Bet-Schemesch opferten Jahwe an diesem Tag Brandopfer und schlachteten Tiere für ein Opfermahl." },
      { number: 16, text: "Die fünf Fürsten der Philister sahen zu und kehrten noch am selben Tag nach Ekron zurück." },
      { number: 17, text: "Fünf Beulen aus Gold hatten die Philister Jahwe als Versöhnungsgeschenk mitgeschickt: eine für Aschdod, eine für Gaza, eine für Aschkelon, eine für Gat und eine für Ekron." },
      { number: 18, text: "Dazu eine größere Anzahl Mäuse aus Gold nach der Zahl aller Ortschaften, die zu den fünf Fürstentümern der Philister gehörten. Noch heute liegt der große Felsblock, auf den sie damals die Lade Jahwes stellten, als Zeuge auf dem Feld des Joschua aus Bet-Schemesch." },
      { number: 19, text: "Doch Jahwe schlug die Leute von Bet-Schemesch, weil sie sich die Lade Jahwes angeschaut* hatten. Siebzig* Männer mussten sterben. Das ganze Volk trauerte, weil Jahwe sie so schwer geschlagen hatte.", footnotes: ["angeschaut. Die meisten englischen Übersetzungen und Kommentare gehen davon aus, dass sie in die Lade hineingeschaut hatten.", "Siebzig. So mit einigen hebräischen Handschriften. Die meisten haben hier Zahlworte für 50.070, was aber weder grammatikalisch noch archäologisch passt und wohl auf eine Textverderbnis zurückgeht."] },
      { number: 20, text: "Und die Leute von Bet-Schemesch sagten: \"Kann überhaupt jemand in der Nähe von diesem heiligen Gott, Jahwe, leben? Er soll von uns wegziehen! Aber zu wem?\"" },
      { number: 21, text: "Sie schickten Boten nach Kirjat-Jearim* und ließen sagen: \"Die Philister haben die Lade Jahwes zurückgebracht. Kommt herunter und holt sie zu euch herauf!\"", footnotes: ["Kirjat-Jearim, \"Wälderstadt\", lag 14 km westlich von Jerusalem."] },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Da kamen die Männer von Kirjat-Jearim und holten die Lade Jahwes zu sich hinauf. Sie brachten sie ins Haus Abinadabs, das auf einem Hügel stand. Seinen Sohn Eleasar weihten sie zum Wächter über die Lade Jahwes." },
      { number: 2, text: "Nachdem die Bundeslade nach Kirjat-Jearim gekommen war, verging viel Zeit. Zwanzig Jahre wurden daraus. Als dann das ganze Volk Israel Jahwe seine Not klagte,", heading: "Samuel als Richter" },
      { number: 3, text: "sagte Samuel zu ihnen: \"Wenn ihr mit eurem ganzen Herzen zu Jahwe umkehren wollt, dann schafft die fremden Götter und Astarten* fort! Wendet euer Herz Jahwe zu und dient ihm allein. Dann wird er euch aus der Gewalt der Philister befreien.\"", footnotes: ["Die Astarte wurde in Kanaan als Fruchtbarkeits- und Liebesgöttin verehrt. Ihr Kult war möglicherweise mit sexuellen Riten verbunden."] },
      { number: 4, text: "Da schafften die Israeliten die Baale* und Astarten fort und verehrten Jahwe allein.", footnotes: ["Baal bedeutet \"Herr\" oder \"Gebieter\". Er wurde als Fruchtbarkeitsgott in Kanaan verehrt."] },
      { number: 5, text: "Dann sagte Samuel: \"Holt alle Männer Israels nach Mizpa* zusammen! Dort will ich Jahwe um Hilfe für euch bitten.\"", footnotes: ["Mizpa. Stadt im Stammesgebiet von Benjamin, 12 km nördlich von Jerusalem."] },
      { number: 6, text: "Sie kamen alle, schöpften Wasser und gossen es vor Jahwe aus.* An diesem Tag fasteten sie auch und bekannten: \"Wir haben uns an Jahwe versündigt.\" In Mizpa schlichtete Samuel auch die Streitfälle der Israeliten.", footnotes: ["schöpften ... aus. Für diese Zeremonie gibt es keine Parallele in der Bibel. Vielleicht symbolisiert es das Ausschütten des Herzens in Beugung und Buße vor Gott."] },
      { number: 7, text: "Als die Philister erfuhren, dass die Männer Israels sich in Mizpa versammelt hatten, rückten die Fürsten der Philister mit einem Heer gegen Israel an. Die Israeliten bekamen Angst vor den Philistern, als sie davon Nachricht erhielten." },
      { number: 8, text: "Sie sagten zu Samuel: \"Hör nicht auf, für uns zu Jahwe um Hilfe zu schreien, dass er uns aus der Gewalt der Philister befreit!\"" },
      { number: 9, text: "Samuel nahm ein Milchlamm und verbrannte es vollständig auf dem Altar für Jahwe. Dabei rief er zu Jahwe um Hilfe für Israel, und Jahwe erhörte ihn." },
      { number: 10, text: "Während Samuel noch opferte, rückten die Philister zum Kampf gegen Israel heran. Aber Jahwe ließ es über den Philistern so schrecklich donnern, dass sie in Panik gerieten und sich vor Israel geschlagen sahen." },
      { number: 11, text: "Die Männer Israels verfolgten und schlugen sie von Mizpa aus bis unterhalb von Bet-Kar*.", footnotes: ["Bet-Kar. Der Ort liegt vermutlich im westlichen Benjamin. Seine genaue Lage ist bis heute unbekannt."] },
      { number: 12, text: "Zur Erinnerung daran stellte Samuel einen Stein zwischen Mizpa und Schen* auf. \"Bis hierher hat uns Jahwe geholfen\", sagte er und nannte ihn Eben-Eser, Stein der Hilfe.", footnotes: ["Schen, Felszahn. Unbekannter Ort, vielleicht eine Schreibweise von Jeschana, das 25 km nördlich von Jerusalem liegt."] },
      { number: 13, text: "Nachdem die Philister so gedemütigt worden waren, kamen sie nicht mehr in das Gebiet Israels. Solange Samuel lebte, stellte Jahwe sich gegen die Philister." },
      { number: 14, text: "Alle Städte zwischen Ekron und Gat, die die Philister Israel abgenommen hatten, fielen wieder an Israel zurück, auch das ganze Gebiet, das dazu gehörte. Mit den Amoritern* lebte Israel ebenfalls in Frieden.", footnotes: ["Amoriter kann sowohl für einen einzelnen Stamm als auch für alle Bewohner Kanaans stehen. Es waren semitische Einwanderer aus der Arabischen Wüste, die um 2000 v.Chr. ins Kulturland eindrangen."] },
      { number: 15, text: "Sein Leben lang war Samuel der Richter Israels." },
      { number: 16, text: "Einmal im Jahr besuchte er die Orte Bet-El*, Gilgal* und Mizpa, um den Israeliten dort Recht zu sprechen.", footnotes: ["Bet-El, der Ort, wo Jakob von der Himmelsleiter träumte, liegt 19 km nördlich von Jerusalem.", "Gilgal wird gewöhnlich mit den Ruinen von Kirbet el-Mafjer identifiziert, 3 km nordöstlich von Jericho. Der Name klingt an das hebr. Wort für Kreis an."] },
      { number: 17, text: "Die übrige Zeit richtete er Israel in seiner Heimatstadt Rama. Dort baute er auch einen Altar für Jahwe." },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Als Samuel alt wurde, setzte er seine Söhne als Richter über Israel ein.", heading: "Israel bekommt einen König" },
      { number: 2, text: "Sein Erstgeborener hieß Joël, der zweite Abija. Sie übten ihr Amt in Beerscheba aus." },
      { number: 3, text: "Seine Söhne folgten aber nicht seinem Vorbild. Sie waren auf Gewinn aus, nahmen Bestechung an und beugten das Recht." },
      { number: 4, text: "Da kamen alle Ältesten Israels bei Samuel in Rama zusammen." },
      { number: 5, text: "Sie sagten zu ihm: \"Du bist alt geworden, und deine Söhne folgen nicht deinem Beispiel. Setz deshalb einen König über uns ein, damit er für Recht bei uns sorgt, wie es bei allen Völkern üblich ist.\"" },
      { number: 6, text: "Aber Samuel missfiel sehr, was sie forderten, und er betete zu Jahwe." },
      { number: 7, text: "Jahwe antwortete ihm: \"Hör auf alles, was sie dir sagen. Denn dieses Volk lehnt nicht dich ab, sondern mich. Ich soll nicht länger ihr König sein." },
      { number: 8, text: "So haben sie es immer wieder gemacht, seit ich sie aus Ägypten geführt habe. Immer wieder sind sie mir untreu geworden und haben anderen Göttern gedient. Das ist bis heute so geblieben. Und mit dir machen sie es jetzt genauso." },
      { number: 9, text: "Hör ruhig auf sie, aber warne sie auch mit aller Deutlichkeit und mach sie mit den Rechten des Königs vertraut, der dann über sie herrschen wird.\"" },
      { number: 10, text: "Samuel gab dem Volk, das einen König von ihm haben wollte, alles weiter, was Jahwe ihm gesagt hatte." },
      { number: 11, text: "Er sagte: \"Wenn ein König über euch herrscht, wird er folgende Rechte haben: Er wird eure Söhne in seinen Dienst holen, damit sie für seine Pferde und Wagen sorgen und vor ihm herlaufen, wenn er ausfährt." },
      { number: 12, text: "Er wird sie zu Hauptleuten und Truppenführern machen, sie müssen seine Felder bestellen und seine Ernte einbringen, sie werden Waffen und Streitwagen herstellen." },
      { number: 13, text: "Eure Töchter wird er holen, damit sie Salben für ihn mischen, für ihn backen und kochen." },
      { number: 14, text: "Eure besten Felder, Weinberge und Olivenhaine wird er seinen Beamten geben." },
      { number: 15, text: "Vom Ertrag eurer Kornfelder und Weinberge wird er den Zehnten fordern und damit seine Hofleute und Diener bezahlen." },
      { number: 16, text: "Auch eure Knechte und Mägde, eure besten jungen Männer und eure Esel wird er holen und für sich arbeiten lassen." },
      { number: 17, text: "Auch von euren Schafen wird er den Zehnten nehmen. Und ihr alle werdet seine Diener sein." },
      { number: 18, text: "Wenn ihr dann wegen eures Königs um Hilfe schreit, den ihr jetzt unbedingt haben wollt, wird euch Jahwe nicht antworten.\"" },
      { number: 19, text: "Aber das Volk wollte nicht auf Samuel hören. \"Nein, wir wollen einen König!\", riefen sie." },
      { number: 20, text: "\"Dann werden wir wie die anderen Völker sein: Unser König wird uns richten, er wird vor uns herziehen und uns im Krieg anführen.\"" },
      { number: 21, text: "Samuel hörte sich alles an, was das Volk ihm sagte, und trug es Jahwe vor." },
      { number: 22, text: "Jahwe sagte zu ihm: \"Hör auf sie und setz einen König über sie ein!\" Dann schickte Samuel die Männer Israels wieder nach Hause." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Damals lebte im Gebiet von Benjamin ein Mann namens Kisch Ben-Abiël. Er war wohlhabend und angesehen. Seine Vorfahren waren Zeror, Bechorat und Afiach aus dem Stamm Benjamin.", heading: "9-15: Saul, der erste König\nSaul kommt zu Samuel" },
      { number: 2, text: "Er hatte einen Sohn namens Saul. Der war jung und stattlich und schöner als alle anderen jungen Männer in Israel. Außerdem war er einen Kopf größer als alle." },
      { number: 3, text: "Einmal waren Sauls Vater Kisch die Eselinnen weggelaufen. Da sagte er zu Saul: \"Nimm einen von den jungen Männern mit und suche sie.\"" },
      { number: 4, text: "Da zogen sie durch das Bergland von Efraïm und das Gebiet von Schalischa*, fanden sie aber nicht. Dann zogen sie durch die Gegend von Schaalim* und das Gebiet von Benjamin.", footnotes: ["Schalischa. Wahrscheinlich das Gebiet um die Stadt Baal-Schalischa, 26 km nordöstlich von Jerusalem.", "Schaalim. Wahrscheinlich ein Gebiet nördlich des Stammes Benjamin."] },
      { number: 5, text: "Als sie in die Gegend von Zuf* kamen, sagte Saul zu seinem Diener: \"Komm, lass uns umkehren. Sonst macht sich mein Vater mehr Sorgen um uns als um die Eselinnen.\"", footnotes: ["Zuf. Gebiet, wo die Zufiter lebten, vermutlich in der Gegend von Rama."] },
      { number: 6, text: "Doch der erwiderte: \"In dieser Stadt dort lebt doch ein angesehener Gottesmann. Alles, was er sagt, trifft sicher ein. Lass uns zu ihm gehen! Vielleicht kann er uns sagen, wo wir uns hinwenden sollen.\"" },
      { number: 7, text: "\"Aber wenn wir hingehen\", entgegnete Saul, \"was wollen wir ihm mitbringen? Unsere Brotbeutel sind leer, und wir haben auch sonst nichts, was wir ihm geben könnten.\"" },
      { number: 8, text: "\"Schau her, ich habe noch ein kleines Silberstück bei mir\", erwiderte der junge Mann. \"Das will ich dem Mann Gottes geben, damit er uns sagt, wohin wir gehen sollen.\"" },
      { number: 9, text: "Damals sagte man in Israel: \"Komm, lass uns zum Seher gehen!\", wenn man etwas von Gott wissen wollte. Früher wurden die Propheten nämlich \"Seher\" genannt." },
      { number: 10, text: "\"Gut\", sagte Saul zu seinem Diener, \"lass uns gehen!\" So gingen sie zu dem Gottesmann in die Stadt." },
      { number: 11, text: "Auf dem Weg zur Stadt trafen sie einige Mädchen, die herunterkamen, um Wasser zu holen. \"Ist der Seher in der Stadt?\", fragten sie die Mädchen." },
      { number: 12, text: "\"Ja, er ist da\", erwiderten sie. \"Beeilt euch, denn gerade heute ist er gekommen, weil das Volk ein Opferfest auf der Höhe feiert." },
      { number: 13, text: "Wenn ihr in die Stadt geht, werdet ihr ihn treffen, bevor er zum Opfermahl hinaufsteigt. Alle werden mit dem Essen auf ihn warten, denn erst, wenn er das Mahl gesegnet hat, dürfen die Gäste davon essen. Wenn ihr euch jetzt beeilt, trefft ihr ihn noch!\"" },
      { number: 14, text: "Sie taten es. Als sie die Stadt betraten, kam ihnen Samuel entgegen. Er wollte gerade zur Opferhöhe hinaufsteigen." },
      { number: 15, text: "Jahwe hatte Samuel schon am Tag vorher offenbart:" },
      { number: 16, text: "\"Morgen um diese Zeit werde ich einen Mann aus Benjamin zu dir schicken. Den sollst du zum Anführer meines Volkes Israel salben. Er wird es aus der Gewalt der Philister befreien, denn ich habe mein Volk angesehen und seinen Hilfeschrei gehört.\"" },
      { number: 17, text: "Als nun Samuel Saul sah, sagte Jahwe zu ihm: \"Das ist der Mann, von dem ich dir gesagt habe, dass er über mein Volk herrschen soll.\"" },
      { number: 18, text: "Da trat Saul im Stadttor auch schon auf Samuel zu und bat: \"Zeig mir doch, wo hier der Seher wohnt!\"" },
      { number: 19, text: "Samuel erwiderte ihm: \"Ich bin der Seher. Steig vor mir auf die Opferhöhe hinauf, denn ihr sollt heute mit mir essen. Morgen früh lass ich dich weiterziehen, und dann sage ich dir auch alles, was du auf dem Herzen hast." },
      { number: 20, text: "Wegen der Eselinnen, die dir heute vor drei Tagen verloren gegangen sind, brauchst du dir keine Gedanken zu machen. Man hat sie gefunden. Aber weißt du, auf wen sich die ganze Hoffnung Israels richtet? – Auf dich und deine Familie!\"" },
      { number: 21, text: "\"Aber ich bin doch ein Benjaminit\", erwiderte Saul. \"Mein Stamm ist der kleinste in Israel und meine Sippe die geringste im ganzen Stamm. Wie kannst du mir so etwas sagen?\"" },
      { number: 22, text: "Samuel führte Saul und seinen Diener in die Halle und wies ihnen die Ehrenplätze an der Tafel zu. Etwa dreißig Mann waren eingeladen." },
      { number: 23, text: "Dann bat er den Koch: \"Bring das Stück her, das ich zurücklegen ließ!\"" },
      { number: 24, text: "Da servierte der Koch die Keule und alles, was dazugehörte, und legte es Saul vor. Samuel sagte: \"Lass es dir schmecken! Es ist extra für dich aufbewahrt worden, als ich das Volk einlud.\" So war Saul an diesem Tag Samuels Gast." },
      { number: 25, text: "Dann gingen sie von der Opferhöhe wieder in die Stadt und unterhielten sich noch lange auf der Dachterrasse." },
      { number: 26, text: "Am nächsten Morgen standen sie früh auf. Schon als die Morgendämmerung anfing, hatte Samuel Saul auf der Dachterrasse zugerufen: \"Steh auf, ich will dich noch ein Stück begleiten!\"" },
      { number: 27, text: "Als sie an die Grenze des Stadtgebietes gekommen waren, sagte er zu Saul: \"Lass deinen Diener vorausgehen!\" Als dieser gegangen war, fuhr Samuel fort: \"Bleib stehen! Ich will dir ein Gotteswort verkünden.\"" },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Samuel nahm die Ölflasche heraus und goss das Öl auf Sauls Kopf. Dann küsste er ihn und sagte: \"Hiermit hat Jahwe dich zum Herrscher über sein Eigentum gesalbt.", heading: "Saul wird zum König gesalbt" },
      { number: 2, text: "Wenn du jetzt weggehst, wirst du beim Rahelsgrab bei Zelzach* an der Grenze von Benjamin zwei Männer treffen. Sie werden dir sagen: 'Die Eselinnen, die du suchen gegangen bist, sind gefunden. Dein Vater sorgt sich jetzt nicht mehr um die Eselinnen, sondern um dich, und überlegt, was er wegen dir unternehmen soll.'", footnotes: ["Zelzach. Die genaue Lage des Ortes ist nicht bekannt."] },
      { number: 3, text: "Wenn du weitergehst, wirst du zur Terebinthe* von Tabor* kommen. Dort werden dir drei Männer begegnen, die zu Gott nach Bet-El hinaufgehen. Einer trägt drei Böckchen, einer drei Brote und der dritte einen Schlauch mit Wein.", footnotes: ["Terebinthe. Belaubter Baum mit breitem Wipfel, der nicht mehr als 7 m hoch wird und als Schattenspender geschätzt ist.", "Tabor. Hier: Ort in der Nähe von Bet-El."] },
      { number: 4, text: "Sie werden dich nach deinem Wohlergehen fragen und dir zwei Brote geben. Die sollst du von ihnen annehmen." },
      { number: 5, text: "Danach wirst du zum Hügel Gottes kommen, wo Wachposten der Philister stehen. Gleich am Stadtrand begegnest du einer Gruppe Propheten, die von der Opferhöhe herabkommen. Vor ihnen her werden Harfe, Tamburin, Flöte und Zither gespielt, und sie weissagen*.", footnotes: ["Weissagen bedeutet normalerweise \"als Sprecher Gottes reden\", hier könnte auch die Entstehung und Wiedergabe geistlicher Musik gemeint sein (wie 1. Chronik 25,1-3, siehe auch 1. Samuel 19,20-24)."] },
      { number: 6, text: "Dann wird der Geist Jahwes über dich kommen und du wirst mit ihnen weissagen. Von da an wirst du ein ganz anderer Mensch sein." },
      { number: 7, text: "Wenn diese Zeichen bei dir eintreffen, dann tu einfach, was dir vor die Hände kommt, denn Gott ist bei dir!" },
      { number: 8, text: "Dann sollst du mir voraus nach Gilgal gehen und sieben Tage auf mich warten. Ich werde zu dir hinabkommen, um Brandopfer darzubringen und Freudenopfer* zu schlachten. Dann werde ich dich wissen lassen, was du tun sollst.\"", footnotes: ["Beim Freudenopfer wurde im Gegensatz zum Brandopfer nur das Fett auf dem Altar verbrannt. Der größte Teil des Tieres durfte bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden."] },
      { number: 9, text: "Als Saul von Samuel wegging, verwandelte Gott sein Herz. Alle Zeichen trafen am selben Tag ein." },
      { number: 10, text: "Als sie an den Hügel kamen, begegnete ihnen eine Gruppe von Propheten. Der Geist Gottes kam über Saul, sodass er mit ihnen weissagte." },
      { number: 11, text: "Und alle, die ihn von früher kannten und sahen, dass er weissagte, fragten einander: \"Was ist denn mit dem Sohn von Kisch geschehen? Wie kommt Saul unter die Propheten?\"" },
      { number: 12, text: "Einer der Umstehenden meinte: \"Von denen kennt man nicht einmal den Anführer!\" Von daher kommt das Sprichwort: \"Ist denn auch Saul unter den Propheten?\"" },
      { number: 13, text: "Als Saul mit dem Weissagen aufgehört hatte, kam er zur Opferstätte." },
      { number: 14, text: "\"Wo seid ihr gewesen?\", fragte Sauls Onkel ihn und seinen Diener. \"Wir haben die Eselinnen gesucht\", antwortete er. \"Und als wir sie nicht finden konnten, gingen wir zu Samuel.\"" },
      { number: 15, text: "\"Was hat er euch denn gesagt?\", wollte der Onkel wissen." },
      { number: 16, text: "Saul erwiderte: \"Er hat uns mitgeteilt, dass die Eselinnen gefunden seien.\" Was Samuel ihm über das Königtum gesagt hatte, erwähnte er aber nicht." },
      { number: 17, text: "Samuel rief das Volk zu Jahwe nach Mizpa.", heading: "Saul wird König über Israel" },
      { number: 18, text: "Dort sagte er zu den Israeliten: \"So spricht Jahwe, der Gott Israels: Ich habe Israel aus Ägypten hierhergeführt, ich habe euch aus der Gewalt der Ägypter und aller anderen Mächte befreit, die euch bedrängt haben." },
      { number: 19, text: "Doch ihr habt heute euren Gott verworfen, der euch aus aller Not und Bedrängnis gerettet hat. Ihr habt zu ihm gesagt: 'Nein, setze einen König über uns!' Nun denn, stellt euch hier vor Jahwe nach Stämmen und Heereseinheiten geordnet auf!\"" },
      { number: 20, text: "Samuel ließ alle Stämme Israels antreten. Das Los fiel auf den Stamm Benjamin." },
      { number: 21, text: "Dann ließ er den Stamm Benjamin nach seinen Sippen antreten. Da fiel das Los auf die Sippe Matri, und dann traf es Saul Ben-Kisch. Man suchte ihn, doch er war nicht zu finden." },
      { number: 22, text: "Da fragten sie Jahwe noch einmal: \"Ist noch ein Mann hierher gekommen?\" Doch Jahwe erwiderte: \"Schaut nach, er hat sich beim Gepäck versteckt!\"" },
      { number: 23, text: "Sie liefen hin und holten ihn. Als er dann in der Menge stand, war er einen Kopf größer als alle." },
      { number: 24, text: "Samuel sagte zum Volk: \"Seht ihr, wen Jahwe ausgewählt hat? Keiner im ganzen Volk ist wie er.\" Da jauchzte das Volk auf und rief: \"Es lebe der König!\"" },
      { number: 25, text: "Samuel trug ihnen nun die Rechte des Königtums vor und schrieb sie anschließend in eine Schriftrolle, die dann im Heiligtum Jahwes niedergelegt wurde. Dann löste er die Versammlung auf und schickte die Leute nach Hause." },
      { number: 26, text: "Auch Saul ging heim nach Gibea. Mit ihm zog eine Schar von Männern, deren Herz Gott berührt hatte." },
      { number: 27, text: "Aber einige niederträchtige Leute sagten: \"Wie soll der uns helfen können?\" Sie hatten nur Verachtung für ihn übrig und brachten ihm auch kein Geschenk. Doch er tat, als hörte er nichts." },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Der Ammoniter* Nahasch zog mit einem Heer vor die Stadt Jabesch* in Gilead* und belagerte sie. Die Männer von Jabesch sagten zu Nahasch: \"Wenn du einen Vertrag mit uns schließt, wollen wir uns dir unterwerfen.\"", heading: "Sauls Sieg über die Ammoniter", footnotes: ["Die Ammoniter lebten nordöstlich vom Toten Meer.", "Jabesch. Stadt am Nordufer des Jabbok, 15 km südöstlich von Bet-Schean und 11 km vom Jordan entfernt.", "Gilead bezeichnet das mittlere, manchmal auch das ganze Ostjordanland."] },
      { number: 2, text: "Doch der Ammoniter Nahasch erwiderte ihnen: \"Unter einer Bedingung lasse ich mich darauf ein: Ich werde jedem von euch das rechte Auge ausstechen, denn ich will Schande über ganz Israel bringen.\"" },
      { number: 3, text: "\"Gib uns sieben Tage Zeit\", sagten die Ältesten von Jabesch zu ihm. \"Wir wollen Boten in alle Gegenden Israels schicken. Wenn uns niemand hilft, kommen wir zu dir hinaus.\"" },
      { number: 4, text: "Die Boten kamen auch nach Gibea, dem Heimatort Sauls. Als sie dem Volk die Lage schilderten, brachen alle in Tränen aus." },
      { number: 5, text: "Saul kam gerade mit seinen Rindern vom Feld und fragte: \"Was ist mit den Leuten los? Warum weinen sie alle?\" Sie berichteten ihm, was die Männer von Jabesch gesagt hatten." },
      { number: 6, text: "Als Saul das hörte, kam der Geist Gottes über ihn, und er wurde sehr zornig." },
      { number: 7, text: "Er schlachtete zwei seiner Rinder und zerstückelte sie. Dann schickte er Boten mit den Stücken in alle Gegenden Israels. Sie sollten sagen: \"Wer nicht mit Saul und Samuel in den Kampf zieht, dessen Rindern wird es ebenso ergehen!\" Da fiel der Schrecken Jahwes auf das ganze Volk, und es meldete sich geschlossen zum Kampf." },
      { number: 8, text: "Bei Besek* musterte er sie. Es waren 300.000 Mann aus Israel und 30.000 Mann aus Juda.", footnotes: ["Besek. Ort im Stammesgebiet von Juda, vielleicht Chirbet Buzqa, 54 km nördlich von Jerusalem."] },
      { number: 9, text: "Die Boten aus Jabesch schickte man mit der Nachricht zurück: \"Morgen, wenn die Sonne heiß wird, werdet ihr befreit.\" Die Botschaft löste große Freude bei den Männern der Stadt aus." },
      { number: 10, text: "Sie ließen den Ammonitern sagen: \"Morgen kommen wir zu euch hinaus. Dann könnt ihr mit uns machen, was ihr wollt.\"" },
      { number: 11, text: "Am nächsten Tag teilte Saul das Heer in drei Abteilungen auf. Noch vor der Morgendämmerung* überfielen sie das Lager. Als der Tag heiß wurde, hatten sie die Ammoniter vernichtend geschlagen. Von den wenigen, die entkamen, blieben nicht zwei beieinander.", footnotes: ["Morgendämmerung. Wörtlich: Morgenwache, d.h. zwischen 2 und 6 Uhr morgens."] },
      { number: 12, text: "Da sagte das Volk zu Samuel: \"Wer hat damals gesagt: 'Soll etwa Saul über uns herrschen?' Her mit den Männern! Wir werden sie töten.\"" },
      { number: 13, text: "Aber Saul wehrte ab: \"An diesem Tag soll niemand von uns getötet werden, denn heute hat Jahwe seinem Volk Israel Rettung geschenkt!\"" },
      { number: 14, text: "Und Samuel sagte zu ihnen: \"Kommt, lasst uns nach Gilgal ziehen und dort das Königtum erneuern!\"" },
      { number: 15, text: "So zogen alle nach Gilgal und bestätigten dort in der Gegenwart Jahwes Saul zum König. Dann schlachteten sie Freudenopfer vor Jahwe. Saul und alle Männer Israels waren glücklich." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Samuel sagte dann zu ganz Israel: \"Seht her, alles, was ihr von mir wolltet, habe ich getan und euch einen König gegeben.", heading: "Samuels Abschiedsrede" },
      { number: 2, text: "Von jetzt an wird er euch vorangehen. Ich bin alt und grau geworden, meine Söhne sind ja unter euch. Von meiner Jugend an habe ich euch geführt, bis heute." },
      { number: 3, text: "Hier stehe ich vor euch, vor Jahwe und seinem gesalbten König. Sprecht es aus, wenn ihr etwas gegen mich habt! Wem habe ich je ein Rind weggenommen oder einen Esel? Wen habe ich erpresst und wen unterdrückt? Von wem habe ich mich bestechen lassen und dann beide Augen zugedrückt? Ich bin bereit, alles zu erstatten!\"" },
      { number: 4, text: "\"Du hast uns nicht erpresst\", erwiderten sie, \"du hast uns nicht misshandelt, du hast von niemand etwas angenommen.\"" },
      { number: 5, text: "Da sagte er: \"Jahwe und sein Gesalbter sind heute Zeugen, dass ihr kein Unrecht an mir gefunden habt.\" – \"Ja, so ist es!\", riefen sie." },
      { number: 6, text: "Dann sagte Samuel zum Volk: \"Es war Jahwe, der Mose und Aaron eingesetzt und eure Väter aus Ägypten geführt hat." },
      { number: 7, text: "Nun tretet her, dass ich vor Jahwe mit euch ins Gericht gehe wegen allem, was Jahwe in seiner Treue für euch und eure Väter getan hat." },
      { number: 8, text: "Als Jakob nach Ägypten gekommen war, schrien eure Vorfahren um Hilfe zu Jahwe. Da schickte er ihnen Mose und Aaron, die eure Väter aus Ägypten führten und sie in dieser Gegend hier wohnen ließen." },
      { number: 9, text: "Aber bald vergaßen sie Jahwe, ihren Gott. Da gab er sie ihren Feinden preis: Sisera, dem Heerführer von Hazor*, den Philistern und dem König von Moab*, die gegen sie kämpften.", footnotes: ["Hazor. Wichtigste kanaanitische Festung im Norden, 14 km nördlich vom See von Galiläa.", "Die Moabiter lebten östlich des Toten Meeres zwischen den Flüssen Arnon und Zered."] },
      { number: 10, text: "Da schrien sie zu Jahwe um Hilfe. 'Es war Unrecht', riefen sie dann, 'dass wir dich verlassen haben, Jahwe, und dass wir die Baale und Astarten verehrten. Befreie uns von unseren Feinden, dann wollen wir dir dienen!'" },
      { number: 11, text: "Da schickte Jahwe Jerub-Baal*, Bedan*, Jiftach und schließlich Samuel, um euch von euren Feinden zu befreien und euch sicher im Land wohnen zu lassen.", footnotes: ["Jerub-Baal, besser bekannt als Gideon (Richter 6,32).", "Bedan wird sonst nicht erwähnt; vielleicht ist Barak (Richter 4,6-7) gemeint."] },
      { number: 12, text: "Als ihr dann aber gesehen habt, dass der Ammoniterkönig Nahasch mit seinem Heer gegen euch zog, sagtet ihr zu mir: 'Nein, ein König soll über uns regieren!', obwohl doch Jahwe, euer Gott, euer König ist." },
      { number: 13, text: "Seht, da ist der König, den ihr haben wolltet! Seht, Jahwe hat einen König über euch gestellt!" },
      { number: 14, text: "Wenn ihr nun Jahwe fürchtet und ihm dient, wenn ihr ihm gehorcht und euch nicht gegen seine Anordnungen stellt, wenn ihr und der König, der über euch herrscht, Jahwe treu bleiben, ist es gut." },
      { number: 15, text: "Wenn ihr Jahwe aber nicht gehorcht und euch seinen Anordnungen widersetzt, wird er sich mit seiner Macht gegen euch stellen wie gegen eure Väter." },
      { number: 16, text: "So tretet jetzt her und seht, welch großes Wunder Jahwe vor euren Augen tun wird!" },
      { number: 17, text: "Es ist gerade Weizenernte. Ich will Jahwe anrufen, dass er Donner und Regen schickt. Dann erkennt ihr, ja, dann werdet ihr sehen, wie groß eure Bosheit in Jahwes Augen war, einen König für euch zu verlangen.\"" },
      { number: 18, text: "Samuel rief Jahwe an und Jahwe ließ es an diesem Tag donnern und regnen. Da fürchtete sich das Volk sehr vor Jahwe und Samuel," },
      { number: 19, text: "und sie sagten zu Samuel: \"Bitte Jahwe, deinen Gott, für deine Diener, dass wir nicht sterben müssen! Denn zu all unseren Sünden haben wir noch die Bosheit hinzugetan, einen König zu verlangen.\"" },
      { number: 20, text: "Samuel erwiderte ihnen: \"Habt keine Angst! Ihr habt zwar all das Böse getan, doch haltet in Zukunft nur treu zu Jahwe und dient ihm von ganzem Herzen!" },
      { number: 21, text: "Weicht ja nicht ab und fangt nicht an, den Nichtsen* nachzulaufen. Sie nützen euch nichts und können euch auch nicht retten, eben weil sie Nichtse sind.", footnotes: ["Nichtse. Gemeint sind irgendwelche Götzen."] },
      { number: 22, text: "Und weil sein großer Name dafür steht, wird Jahwe sein Volk nicht verlassen, denn es hat ihm nun einmal gefallen, euch zu seinem Volk zu machen." },
      { number: 23, text: "Auch ich werde auf keinen Fall aufhören, für euch zu beten! Denn dann würde ich mich an Jahwe versündigen. Ich werde euch weiter den guten und richtigen Weg zeigen." },
      { number: 24, text: "Ehrt nur Jahwe und dient ihm treu von ganzem Herzen! Seht doch, was für große Dinge er an euch getan hat!" },
      { number: 25, text: "Wenn ihr aber trotzdem Böses tut, werdet ihr samt eurem König weggerafft.\"" },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Saul war 30* Jahre alt, als er König wurde, und regierte eine Zweizahl* von Jahren über Israel.", heading: "Samuel widersteht Saul", footnotes: ["30. Die Zahl fehlt im hebräischen Text. In den meisten Handschriften der LXX fehlt der ganze Vers. Nur einige Manuskripte nennen die Zahl 30.", "Zweizahl. Gemeint ist eventuell eine zweistellige Zahl. Nach Apostelgeschichte 13,21 waren es 40 Jahre. Möglicherweise kann die Zwei auch auf den folgenden Vers bezogen werden: \"Nachdem er zwei Jahre in Israel regiert hatte, wählte er sich ...\""] },
      { number: 2, text: "Saul wählte sich 3000 Israeliten aus. 2000 sollten unter seinem Befehl in Michmas* und auf den Höhen von Bet-El stehen und 1000 unter Jonatan bei Gibea in Benjamin. Den Rest des Volkes entließ er wieder nach Hause.", footnotes: ["Michmas war ein Dorf im Stammesgebiet von Benjamin, 12 km nördlich von Jerusalem."] },
      { number: 3, text: "Jonatan erschlug die Wachposten der Philister in Geba*. Als das bei den Philistern bekannt wurde, ließ Saul im ganzen Land das Widderhorn blasen, denn er wollte, dass die Hebräer es hörten.", footnotes: ["Geba liegt zwischen Michmas und Gibea, etwa 12 km nördlich von Jerusalem."] },
      { number: 4, text: "Überall in Israel wurde ausgerufen: \"Saul hat die Wachposten der Philister geschlagen! Dadurch hat sich Israel bei den Philistern verhasst gemacht.\" So wurde das Volk nach Gilgal zusammengerufen, um unter Sauls Führung zu kämpfen." },
      { number: 5, text: "Auch die Philister sammelten sich zum Kampf gegen Israel. 3000* Streitwagen und 6000 Gespanne, dazu Fußkämpfer wie Sand am Meer. Ihr Lager schlugen sie bei Michmas, östlich von Bet-Awen* auf.", footnotes: ["3000. So mit der LXX. Hebräisch: 30.000.", "Bet-Awen. Stadt an der Nordgrenze von Benjamin, 12 km nordöstlich von Jerusalem."] },
      { number: 6, text: "Als die Israeliten sahen, dass sie durch diese Menge in Not kommen würden, versteckten sie sich in Höhlen und in Dornengestrüpp, in Felsen, Grabkammern und Zisternen." },
      { number: 7, text: "Einige Hebräer flohen sogar über den Jordan ins Gebiet von Gad* und Gilead. Saul war immer noch in Gilgal. Und das ganze Volk, das bei ihm war, zitterte vor Angst.", footnotes: ["Gad. Stammesgebiet nordöstlich des Toten Meeres an der Ostseite des Jordan-Tals."] },
      { number: 8, text: "Er wartete sieben Tage bis zu der von Samuel bestimmten Zeit. Als Samuel nicht nach Gilgal kam, fingen die Leute an wegzulaufen." },
      { number: 9, text: "Da sagte Saul: \"Bringt mir die Tiere für das Brand- und Freudenopfer her!\" Dann brachte er selbst das Opfer dar." },
      { number: 10, text: "Als er gerade mit dem Brandopfer fertig war, kam Samuel. Saul ging ihm zum Segensgruß entgegen." },
      { number: 11, text: "\"Was hast du da getan?\", fragte Samuel. \"Ich sah, dass das Volk mir davonlief\", erwiderte Saul, \"und du kamst nicht zur vereinbarten Zeit, und die Philister standen schon in Michmas." },
      { number: 12, text: "Da dachte ich: Nun werden sie nach Gilgal herunterkommen, und ich habe Jahwe noch nicht gnädig gestimmt. Da habe ich es gewagt und das Brandopfer selbst dargebracht.\"" },
      { number: 13, text: "\"Das war sehr dumm von dir!\", sagte Samuel. \"Du hast den Befehl von Jahwe, deinem Gott, nicht ausgeführt. Denn gerade jetzt hätte er dein Königtum über Israel für immer bestätigt." },
      { number: 14, text: "Aber nun wird es keinen Bestand haben. Jahwe hat sich einen Mann gesucht, der ihm gefällt, und ihn zum Führer über sein Volk bestimmt. Denn du hast dich nicht an das Gebot Jahwes gehalten.\"" },
      { number: 15, text: "Samuel verließ Gilgal und ging nach Gibea in Benjamin. Als Saul seine Leute musterte, waren es noch etwa 600 Mann.", heading: "Israel ohne Waffen" },
      { number: 16, text: "Saul und sein Sohn Jonatan blieben bei Geba in Benjamin. Die Philister hatten ihr Lager bei Michmas." },
      { number: 17, text: "Jetzt brachen aus dem Lager der Philister drei Abteilungen auf, die das Land verwüsten sollten. Eine Truppenabteilung zog in Richtung Ofra*, im Gebiet von Schual.", footnotes: ["Ofra. Das heutige et Tajibe, das auf einer Anhöhe 9 km nördlich von Michmas liegt."] },
      { number: 18, text: "Die zweite zog in Richtung Bet-Horon* und die dritte in Richtung des Höhenzuges, von dem aus das Hyänental und die Wüste zu sehen sind.", footnotes: ["Bet-Horon. Wichtiger Passweg vom Gebirge in die Schefela, das fruchtbare Hügelland Judas. Er wird von den Orten Oberes Bet-Horon (617 m ü. NN) und Unteres Bet-Horon (399 m ü. NN) beherrscht."] },
      { number: 19, text: "Damals gab es in ganz Israel keinen Schmied, denn die Philister wollten verhindern, dass die Hebräer sich Schwerter oder Speere machten." },
      { number: 20, text: "Deshalb musste jeder Israelit zu den Philistern gehen, wenn er seine Pflugschar, einen Spaten, ein Beil oder eine Sichel schärfen lassen wollte." },
      { number: 21, text: "Bei Pflugschar und Spaten kostete das zwei Drittel eines Silberstücks, bei einem Dreizink, einem Beil und dem Ochsenstachel* ein Drittel.", footnotes: ["Ochsenstachel. Zum Antreiben der Rinder verwendete man einen Stab mit einer scharfen Spitze."] },
      { number: 22, text: "So kam es, dass am Tag des Kampfes keiner von den Männern Israels, die Saul und Jonatan folgten, ein Schwert oder einen Speer hatte. Nur Saul und sein Sohn besaßen welche." },
      { number: 23, text: "Ein Posten der Philister sollte den Pass bei Michmas sichern." },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Eines Tages sagte Jonatan zu seinem Waffenträger: \"Los, gehen wir zu dem Posten der Philister dort drüben!\" Seinem Vater aber sagte er nichts davon.", heading: "Jonatans Heldentat" },
      { number: 2, text: "Saul saß zu dieser Zeit unter dem Granatapfelbaum, der am Rand von Gibea steht. Etwa 600 Mann waren bei ihm." },
      { number: 3, text: "Ahija Ben-Ahitub, der Bruder von Ikabod und Sohn von Pinhas Ben-Eli, dem Sohn von Jahwes Priester in Schilo, trug das Efod. Auch von den Männern Sauls wusste niemand, dass Jonatan weggegangen war." },
      { number: 4, text: "Um zu dem Posten der Philister hinüberzugelangen, wählte Jonatan einen Weg zwischen zwei Felszacken hindurch. Einen nannte man Bozez, den Glänzenden, den anderen Senne, den Stachel." },
      { number: 5, text: "Sie ragten wie Säulen auf, die eine im Norden auf der Seite von Michmas, die andere im Süden auf der Seite von Geba." },
      { number: 6, text: "Jonatan sagte zu seinem Waffenträger: \"Komm, wir gehen zum Posten dieser Unbeschnittenen* dort drüben. Vielleicht wird Jahwe etwas für uns tun, denn für ihn spielt es keine Rolle, ob wir viele oder wenige sind.\"", footnotes: ["Unbeschnittene. Verächtlicher Ausdruck für Menschen, die nicht zum Bund Gottes gehörten. Siehe 1. Mose 17,9-14!"] },
      { number: 7, text: "\"Tu, was du für richtig hältst\", erwiderte sein Waffenträger, \"ich bin immer dabei!\"" },
      { number: 8, text: "\"Pass auf!\", sagte Jonatan. \"Wir gehen ganz offen auf die Männer zu." },
      { number: 9, text: "Wenn sie dann zu uns sagen: 'Bleibt stehen, bis wir bei euch sind!', dann bleiben wir stehen und steigen nicht zu ihnen hinauf." },
      { number: 10, text: "Wenn sie aber sagen: 'Kommt herauf zu uns!', dann klettern wir hinauf, denn dann hat Jahwe sie in unsere Hand gegeben. Das soll uns das Zeichen sein.\"" },
      { number: 11, text: "So zeigten sich beide dem Posten der Philister. \"Sieh da!\", riefen die Philister. \"Die Hebräer kommen aus den Löchern hervor, in die sie sich verkrochen haben.\"" },
      { number: 12, text: "Die Wachen riefen Jonatan und seinem Waffenträger zu: \"Kommt rauf zu uns, dann werden wir es euch schon zeigen!\" Da sagte Jonatan zu seinem Waffenträger: \"Steig mir nach, denn Jahwe hat sie in die Hand Israels gegeben!\"" },
      { number: 13, text: "Auf allen Vieren kletterte Jonatan hinauf und sein Waffenträger hinter ihm her. Jonatan schlug die Philister nieder und sein Waffenträger versetzte ihnen den Todesstoß." },
      { number: 14, text: "Dieser erste Schlag, den Jonatan mit seinem Waffenträger führte, traf etwa 20 Mann – auf einer Fläche von der Größe eines halben Ackers*.", footnotes: ["Acker. Wörtlich: der halben Pflugstrecke eines Ackerjochs. Ein Joch ist die Fläche, die von einem Joch Ochsen an einem Tag gepflügt werden konnte, etwa 1600 Quadratmeter, die Hälfte davon also 800."] },
      { number: 15, text: "Da brach eine Panik im ganzen Heer der Philister aus: bei denen im Lager und bei denen im Gelände, auch bei der Postenkette und bei denen, die zur Verwüstung des Landes ausgezogen waren. Dazu bebte die Erde. Ein Schrecken Gottes war auf sie gefallen." },
      { number: 16, text: "Die Späher Sauls in Gibea in Benjamin bemerkten das lärmende Getümmel, das hin und her wogte.", heading: "Der Sieg über die Philister" },
      { number: 17, text: "Saul befahl seinen Leuten: \"Lasst antreten und seht nach, wer von uns weggegangen ist!\" Da stellte sich heraus, dass Jonatan und sein Waffenträger fehlten." },
      { number: 18, text: "\"Bring die Lade Gottes* her!\", sagte Saul zu Ahija. Die Bundeslade befand sich nämlich im Lager der Israeliten.", footnotes: ["Lade Gottes. Die LXX übersetzt hier und auch im nächsten Satz: das Efod."] },
      { number: 19, text: "Aber während er noch mit dem Priester redete, steigerte sich der Tumult im Lager der Philister so sehr, dass Saul zu ihm sagte: \"Nein, lass es!\"" },
      { number: 20, text: "Saul und seine Leute sammelten sich und liefen zu dem Kampfgeschehen. Da sahen sie, dass einer gegen den anderen kämpfte. Es war ein großes Durcheinander." },
      { number: 21, text: "Und die Hebräer, die sich bisher zu den Philistern gehalten hatten und mit ihnen in den Kampf gezogen waren, wollten jetzt bei den Israeliten sein, die zu Saul und Jonatan standen." },
      { number: 22, text: "Und als die Israeliten, die sich im Bergland von Efraïm versteckt hatten, von der Flucht der Philister hörten, nahmen auch sie die Verfolgung auf." },
      { number: 23, text: "So rettete Jahwe Israel an diesem Tag. Der Kampf zog sich bis über Bet-Awen hinaus." },
      { number: 24, text: "Vorwärtsgetrieben wurden die Männer Israels an jenem Tag durch einen Schwur Sauls. Saul hatte gesagt: \"Verflucht sei jeder, der vor dem Abend etwas isst, bis ich mich an meinen Feinden gerächt habe!\" Daher nahm keiner von den Leuten etwas zu sich.", heading: "Sauls voreiliger Schwur" },
      { number: 25, text: "Zu dieser Zeit gab es überall in der Gegend Honig von wilden Bienen." },
      { number: 26, text: "Als die Leute an den Stöcken vorbeikamen, flossen diese von Honig über. Aber niemand wagte es, davon zu kosten, denn sie fürchteten Sauls Fluch." },
      { number: 27, text: "Jonatan wusste nichts von dem Fluch, mit dem sein Vater das Volk belegt hatte. Er tauchte den Stab, den er in der Hand hatte, mit der Spitze in eine Honigwabe und aß von dem Honig. Da leuchteten seine Augen auf." },
      { number: 28, text: "Einer von den Männern sagte zu ihm: \"Dein Vater hat jeden mit einem Fluch bedroht, der heute etwas isst. Darum sind wir alle so erschöpft.\"" },
      { number: 29, text: "Da sagte Jonatan: \"Mein Vater bringt das Land ins Unglück. Seht doch, wie meine Augen leuchten, weil ich dieses bisschen Honig gekostet habe." },
      { number: 30, text: "Wie viel größer wäre unser Sieg gewesen, wenn die Leute sich an der Beute ihrer Feinde hätten satt essen können. So ist der Schlag gegen die Philister nicht heftig genug.\"" },
      { number: 31, text: "Sie verfolgten die Philister an jenem Tag bis nach Ajalon*. Dann waren alle erschöpft.", footnotes: ["Ajalon. Stadt in der Schefela, 21 km nordwestlich von Jerusalem."] },
      { number: 32, text: "Sie stürzten sich nun auf die Beutetiere und schlachteten Schafe, Rinder und Kälber einfach auf der Erde und aßen das blutige Fleisch." },
      { number: 33, text: "Man berichtete Saul: \"Pass auf! Das Volk macht sich schuldig vor Jahwe. Sie essen Fleisch, das noch blutig ist!\" – \"Ihr seid Gott untreu geworden!\", rief Saul. \"Wälzt sofort einen großen Stein zu mir her!\"" },
      { number: 34, text: "Dann ordnete er an: \"Geht unter das Volk und sagt jedem, dass er sein Rind oder Schaf zu mir bringen und es hier schlachten soll. Dann können sie es essen, ohne sich an Jahwe zu versündigen.\" Deshalb brachten in dieser Nacht alle ihre Tiere zum Schlachten an diesen Platz." },
      { number: 35, text: "Dann baute Saul Jahwe einen Altar. Das war der erste, den er für ihn gebaut hatte." },
      { number: 36, text: "Saul sagte: \"Lasst uns noch in der Nacht den Philistern nachjagen. Wir wollen sie ausplündern und keinen von ihnen bis zum Morgen übrig lassen!\" – \"Tu, was du für richtig hältst!\", riefen die Männer. Aber der Priester sagte: \"Lasst uns erst hier vor Gott treten!\"" },
      { number: 37, text: "Saul fragte Gott: \"Soll ich die Philister bis in die Ebene verfolgen? Wirst du sie in die Hand Israels geben?\" Aber Gott gab Saul keine Antwort." },
      { number: 38, text: "Da rief Saul alle Truppenführer zu sich und sagte: \"Es muss heute jemand Schuld auf sich geladen haben. Findet heraus, wer es war!" },
      { number: 39, text: "So wahr Jahwe lebt, der Israel gerettet hat, der Schuldige muss sterben, und wenn es mein Sohn Jonatan wäre!\" Aber niemand aus dem Volk antwortete ihm." },
      { number: 40, text: "Da sagte er zu den Israeliten: \"Stellt euch hier auf die eine Seite! Ich werde mit meinem Sohn Jonatan auf der anderen stehen.\" – \"Tu, was du für richtig hältst\", entgegnete das Volk." },
      { number: 41, text: "Da rief Saul zu Jahwe: \"Gott Israels, gib uns volle Klarheit!\" Da wurden Jonatan und Saul getroffen. Das Volk ging frei aus." },
      { number: 42, text: "\"Werft jetzt das Los zwischen mir und meinem Sohn!\", befahl Saul. Da wurde Jonatan getroffen." },
      { number: 43, text: "\"Sag mir, was hast du getan?\", forderte Saul seinen Sohn Jonatan auf. Dieser bekannte: \"Ich habe die Spitze meines Stabs in Honig getaucht und ein wenig davon gekostet und muss nun dafür sterben.\"" },
      { number: 44, text: "\"Gott soll mir dies und jenes antun: Ja, du musst sterben!\", sagte Saul." },
      { number: 45, text: "Aber das Volk rief: \"Soll Jonatan sterben, der diesen großen Sieg für Israel errungen hat? Auf keinen Fall! So wahr Jahwe lebt, kein Haar soll ihm gekrümmt werden! Diese Taten heute hat er nur mit Gott vollbringen können.\" So löste das Volk Jonatan aus, dass er nicht sterben musste." },
      { number: 46, text: "Saul verfolgte die Philister nicht weiter und kehrte um. Auch die Philister kehrten in ihr Gebiet zurück." },
      { number: 47, text: "Nachdem Saul die Königsherrschaft über Israel bekommen hatte, kämpfte er gegen alle seine Feinde ringsum: gegen die Moabiter, die Ammoniter, die Edomiter*, gegen die Könige von Zoba* und gegen die Philister. Und alle bestrafte er.", heading: "Sauls Kriege", footnotes: ["Die Edomiter waren Nachkommen Esaus und bewohnten das Land östlich der Araba und südlich vom Toten Meer.", "Zoba war ein kleines Königreich nördlich von Damaskus, das David später besiegt hatte (2. Samuel 8,3-12; 10,6-19)."] },
      { number: 48, text: "Er war ein tapferer Mann und besiegte die Amalekiter*. Er befreite Israel von allen, die es ausplünderten.", footnotes: ["Die Amalekiter lebten als Nomaden im Negev, südlich von Beerscheba."] },
      { number: 49, text: "Sauls Söhne hießen Jonatan, Jischwi und Malkischua. Seine beiden Töchter hießen Merab und Michal. Merab war die Erstgeborene.", heading: "Sauls Familie" },
      { number: 50, text: "Sauls Frau hieß Ahinoam und war eine Tochter von Ahimaaz. Sein Heerführer war Abner Ben-Ner, der Sohn seines Onkels," },
      { number: 51, text: "denn Kisch, der Vater Sauls, und Ner, der Vater Abners, waren Söhne von Abiël." },
      { number: 52, text: "Der harte Krieg mit den Philistern hörte nicht auf, solange Saul lebte. Darum nahm Saul jeden tapferen und kriegstüchtigen Mann, den er finden konnte, in seinen Dienst." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Samuel kam zu Saul und sagte: \"Jahwe hatte mich beauftragt, dich zum König über sein Volk Israel zu salben. So höre nun auf die Worte Jahwes!", heading: "Sauls Sieg und seine Verwerfung" },
      { number: 2, text: "So spricht Jahwe, der Allmächtige: 'Ich habe bedacht, was die Amalekiter Israel angetan haben, wie sie sich dem Volk in den Weg stellten, als es aus Ägypten heraufzog." },
      { number: 3, text: "Nun zieh gegen sie in den Kampf, schlage sie und vollstrecke den Bann an ihnen. Schone keinen, sondern töte Mann und Frau, Kind und Säugling, Rind und Schaf, Kamel und Esel!'\"" },
      { number: 4, text: "Da bot Saul das Volk auf und musterte es in Telem*. Es waren 200.000 Mann zu Fuß und 10.000 Männer aus Juda.", footnotes: ["Telem. Stadt im Negev im Süden von Juda, etwa 18 km östlich von Beerscheba."] },
      { number: 5, text: "Saul kam bis zur Stadt der Amalekiter und legte sich im Tal auf die Lauer." },
      { number: 6, text: "Den Kenitern* ließ er sagen: \"Zieht weg, trennt euch von den Amalekitern, dass wir euch nicht mit ihnen vernichten. Ihr seid uns damals freundlich begegnet, als wir aus Ägypten kamen.\" Da verließen die Keniter das Gebiet Amaleks.", footnotes: ["Die Keniter waren ein mit den Midianitern verwandter Beduinenstamm vom Sinai. Mose hatte eine Keniterin geheiratet (2. Mose 2,16.21-22) und einige Keniter hatten sich den Israeliten angeschlossen (Richter 1,16; 4,17-23)."] },
      { number: 7, text: "Saul schlug die Amalekiter von Hawila* bis nach Schur* an der ägyptischen Grenze.", footnotes: ["Hawila. Das Gebiet lag wahrscheinlich im Nordosten der Sinai-Halbinsel.", "Die Wüste Schur lag zwischen dem \"Bach Ägyptens\" und dem heutigen Suez-Kanal. Der Ort Schur war eventuell das heutige Tell Fara, ein Vorposten der Ägypter."] },
      { number: 8, text: "Agag, den König der Amalekiter, fing er lebendig. An seinem ganzen Volk vollstreckte er den Bann und ließ alle mit dem Schwert töten." },
      { number: 9, text: "Aber an Agag und an den besten Schafen und Rindern, auch an denen vom zweiten Wurf und den Lämmern und an allem, was wertvoll war, wollten sie den Bann nicht vollstrecken. Sie vollstreckten den Bann nur an dem Zeug, das man verachtet und wegwirft." },
      { number: 10, text: "Da kam das Wort Jahwes zu Samuel:" },
      { number: 11, text: "\"Es ist mir leid, Saul zum König gemacht zu haben, denn er hat sich von mir abgewandt und meine Befehle nicht befolgt.\" Samuel war tief betroffen und schrie die ganze Nacht zu Jahwe." },
      { number: 12, text: "Früh am Morgen machte er sich auf den Weg zu Saul. Man berichtete ihm: \"Saul ist nach Karmel* gekommen, und – stell dir vor –, er hat sich dort ein Denkmal aufgerichtet! Dann ist er nach Gilgal weitergezogen.\"", footnotes: ["Karmel. Hier ist wahrscheinlich der Ort gemeint, der 12 km südöstlich von Hebron am Rand der Judäischen Wüste liegt."] },
      { number: 13, text: "Als Samuel zu Saul kam, empfing dieser ihn mit den Worten: \"Jahwe segne dich! Ich habe den Befehl Jahwes ausgeführt.\"" },
      { number: 14, text: "\"Aber was höre ich da für Schafe blöken und welche Rinder höre ich brüllen?\", entgegnete Samuel." },
      { number: 15, text: "\"Man hat sie von den Amalekitern mitkommen lassen\", erwiderte Saul. \"Das Volk hat die besten Schafe und Rinder verschont, um sie Jahwe, deinem Gott, zu opfern. An allen anderen haben wir den Bann vollstreckt.\"" },
      { number: 16, text: "\"Hör auf!\", sagte Samuel zu Saul. \"Ich will dir verkünden, was Jahwe mir in dieser Nacht mitgeteilt hat.\" – \"Sprich!\", erwiderte Saul," },
      { number: 17, text: "und Samuel sagte: \"Als du noch gering von dir dachtest, wurdest du das Oberhaupt der Stämme Israels. Zum König hat Jahwe dich gesalbt." },
      { number: 18, text: "Dann schickte er dich los und sagte: 'Geh und vollstrecke den Bann an diesen sündigen Amalekitern! Kämpfe mit ihnen, bis du sie vernichtet hast!'" },
      { number: 19, text: "Warum hast du nicht auf Jahwe gehört? Warum bist du über die Beute hergefallen und hast getan, was Jahwe missfällt?\"" },
      { number: 20, text: "\"Aber ich habe doch auf Jahwe gehört\", erwiderte Saul. \"Ich bin den Weg gegangen, auf den er mich geschickt hat. Ich habe Agag, den König von Amalek, hergebracht und an allen Amalekitern den Bann vollstreckt." },
      { number: 21, text: "Aber das Volk hat die besten von den erbeuteten Schafen und Rindern am Leben gelassen, um sie Jahwe, deinem Gott, in Gilgal zu opfern.\"" },
      { number: 22, text: "Doch Samuel erwiderte:\"Freut Jahwe sich mehr über Opfer, / die man schlachtet und verbrennt, / als daran, dass man ihm gehorcht? / Merk dir: Gehorsam ist ihm wichtiger als Opfer, / auf ihn zu hören, ist ihm mehr wert als das Fett vieler Schafböcke." },
      { number: 23, text: "Ungehorsam ist für ihn eine Sünde wie die Zauberei, / Auflehnung gegen ihn so schlimm wie Götzendienst. / Weil du das Wort Jahwes verworfen hast, / verwirft er auch dich als König.\"" },
      { number: 24, text: "Da sagte Saul zu Samuel: \"Ich habe gesündigt, denn ich habe mich über den Befehl Jahwes und über deine Anweisungen hinweggesetzt. Ich habe mich vor meinen Leuten gefürchtet und ihnen ihren Willen gelassen." },
      { number: 25, text: "Vergib mir bitte meine Sünde und komm mit mir zurück, dass ich vor Jahwe anbete!\"" },
      { number: 26, text: "Aber Samuel sagte zu ihm: \"Ich gehe nicht mit dir zurück. Du hast das Wort Jahwes verworfen, und Jahwe hat nun auch dich verworfen. Du kannst nicht mehr König über Israel sein.\"" },
      { number: 27, text: "Samuel drehte sich um und wollte weggehen. Aber Saul hielt ihn am Mantel fest, sodass ein Zipfel davon abriss." },
      { number: 28, text: "Da sagte Samuel zu ihm: \"Genauso hat Jahwe heute das Königtum Israels von dir abgerissen und es einem anderen gegeben, der besser ist als du." },
      { number: 29, text: "Er, der Ruhm seines Volkes Israel, lügt nicht, und es tut ihm auch nicht leid. Er ist nicht wie ein Mensch, der seine Entscheidung bereut.\"" },
      { number: 30, text: "\"Ja, ich habe gesündigt\", sagte Saul. \"Aber ehre mich doch vor den Ältesten meines Volkes und vor Israel und kehre mit mir um, dass ich mich vor Jahwe, deinem Gott, niederwerfe!\"" },
      { number: 31, text: "Samuel tat es und ging mit Saul zurück. Und Saul warf sich vor Jahwe nieder." },
      { number: 32, text: "Dann sagte Samuel: \"Bringt Agag, den König von Amalek, zu mir her!\" Agag ging gelassen* auf ihn zu und sagte: \"Sei's drum, die Todesgefahr ist vorbei!\"", footnotes: ["gelassen. Die Bedeutung des hebräischen Wortes ist unklar. Vielleicht bedeutet es wie Hiob 38,31\"in Fesseln\". Dann müsste auch die Aussage negativ übersetzt werden: \"Ja, der Tod ist sehr bitter.\""] },
      { number: 33, text: "Aber Samuel sagte:\"So, wie dein Schwert Frauen um die Kinder brachte, / sei auch deine Mutter um ihr Kind gebracht!\"Vor Jahwe in Gilgal hieb Samuel Agag in Stücke." },
      { number: 34, text: "Dann kehrte Samuel nach Rama zurück. Und auch Saul ging nach Hause in seine Stadt Gibea." },
      { number: 35, text: "Samuel sah Saul bis zu seinem Tod nicht mehr. Er trauerte um ihn, weil es Jahwe leid tat, dass er Saul zum König über Israel gemacht hatte." },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Jahwe sagte zu Samuel: \"Wie lange willst du noch um Saul trauern? Ich habe ihn verworfen. Er soll nicht mehr König über Israel sein. Füll dein Horn mit Salböl und mach dich auf den Weg! Ich schicke dich zu Isai von Bethlehem, weil ich mir einen seiner Söhne als König ausgesucht habe.\"", heading: "16-31: David – Vorbereitung zum Königtum\nDavids Wahl zum König (16-17)\nDavid wird zum König gesalbt" },
      { number: 2, text: "\"Aber wie kann ich denn gehen?\", erwiderte Samuel. \"Saul wird es erfahren und mich umbringen.\" Jahwe sagte: \"Nimm eine junge Kuh mit und sag dort: 'Ich bin gekommen, um Jahwe ein Opfer zu bringen.'" },
      { number: 3, text: "Lade Isai zu dem Schlachtopfer ein. Dann werde ich dir zeigen, was du tun musst. Du sollst mir den salben, den ich dir nennen werde.\"" },
      { number: 4, text: "Samuel tat, was Jahwe ihm befohlen hatte, und ging nach Bethlehem. Da eilten ihm die Ältesten der Stadt voller Angst entgegen. \"Bringst du Frieden?\", fragten sie." },
      { number: 5, text: "\"Ja, Frieden\", antwortete er. \"Ich bin gekommen, um Jahwe zu opfern. Heiligt* euch und kommt mit mir zum Schlachtopfer!\" Dann heiligte er Isai und seine Söhne und lud sie zum Opfermahl ein.", footnotes: ["Sich heiligen bedeutet, sich geistlich darauf einstellen und die Reinigungsvorschriften für den Opfernden einhalten (siehe Josua 3,5)."] },
      { number: 6, text: "Als sie dann kamen und er Eliab sah, dachte er: \"Hier steht Jahwes Gesalbter vor Gott.\"" },
      { number: 7, text: "Aber Jahwe sagte zu Samuel: \"Sieh nicht auf seine Erscheinung und seinen hohen Wuchs! Ich habe ihn verworfen. Es ist nicht so, wie der Mensch es sieht. Ein Mensch sieht, was vor Augen ist, Jahwe aber sieht auf das Herz.\"" },
      { number: 8, text: "Dann rief Isai Abinadab und ließ ihn vor Samuel treten. Doch dieser sagte: \"Auch ihn hat Jahwe nicht erwählt.\"" },
      { number: 9, text: "Nun ließ Isai Schamma kommen, aber Samuel sagte: \"Auch ihn hat Jahwe nicht erwählt.\"" },
      { number: 10, text: "So ließ Isai sieben seiner Söhne an Samuel vorbeigehen. Aber Samuel sagte zu ihm: \"Von diesen hat Jahwe keinen erwählt.\"" },
      { number: 11, text: "Deshalb fragte er: \"Sind das alle deine Söhne?\" Isai sagte: \"Der Jüngste ist noch übrig. Aber er hütet gerade die Schafe.\" Da sagte Samuel: \"Schick jemand hin und lass ihn holen! Wir werden uns nicht zum Mahl hinsetzen, bevor er gekommen ist.\"" },
      { number: 12, text: "So schickte Isai einen Boten und ließ David kommen. Der Junge war rotblond, hatte schöne Augen und sah gut aus. Da sagte Jahwe: \"Auf, salbe ihn! Er ist es.\"" },
      { number: 13, text: "Samuel nahm das Ölhorn und salbte David im Kreis seiner Brüder. Von diesem Tag an kam der Geist Gottes über David und verließ ihn nicht mehr. Samuel kehrte nach Rama zurück." },
      { number: 14, text: "Von Saul jedoch wich der Geist Jahwes. Und ein böser Geist, den Jahwe geschickt hatte, begann ihn zu ängstigen.", heading: "David am Hof Sauls" },
      { number: 15, text: "Sauls Diener sagten zu ihm: \"Offenbar hat Gott dir einen bösen Geist geschickt, der dir Angst macht." },
      { number: 16, text: "Unser Herr möge seinen Dienern hier befehlen, dass sie einen Mann suchen, der Zither spielen kann. Wenn dann der böse Geist von Gott über dich kommt, kann er dir vorspielen, und es wird dir besser gehen.\"" },
      { number: 17, text: "Da sagte Saul zu seinen Dienern: \"Sucht mir einen guten Zitherspieler und bringt ihn her.\"" },
      { number: 18, text: "Einer der jungen Männer sagte: \"Ich kenne einen Sohn Isais aus Bethlehem, der gut spielen kann und außerdem ein tüchtiger Kämpfer ist. Er versteht es, immer das richtige Wort zu sagen, und sieht auch noch gut aus. Jahwe ist mit ihm.\"" },
      { number: 19, text: "Da schickte Saul Boten zu Isai und ließ ihm sagen: \"Schick mir deinen Sohn David, der die Schafe hütet.\"" },
      { number: 20, text: "Isai holte einen Esel und belud ihn mit Broten. Dazu gab er einen Schlauch Wein und ein Ziegenböckchen und schickte alles mit David zu Saul." },
      { number: 21, text: "So kam David zu Saul und trat in seinen Dienst. Saul gewann ihn sehr lieb und machte ihn zu seinem Waffenträger." },
      { number: 22, text: "Isai ließ er sagen: \"Lass David in meinem Dienst bleiben. Ich bin sehr zufrieden mit ihm.\"" },
      { number: 23, text: "Immer, wenn dieser Geist von Gott über Saul kam, nahm David die Zither und spielte darauf. So fand Saul Erleichterung. Es ging ihm besser, und der böse Geist verließ ihn." },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Die Philister zogen ihre Streitmacht bei Socho* zusammen, das zum Gebiet von Juda gehörte. Ihr Lager schlugen sie bei Efes-Dammim* auf, das zwischen Socho und Aseka* liegt.", heading: "David besiegt Goliat", footnotes: ["Dieses Socho lag 27 km westlich von Jerusalem.", "Efes-Dammim lag wahrscheinlich auf der Südseite des Terebinthentals, etwa 1,5 km südöstlich von Aseka.", "Aseka. Stadt an der Grenze zwischen Juda und der Küstenebene am Mittelmeer, 24 km nordwestlich von Hebron."] },
      { number: 2, text: "Saul hatte die wehrfähigen Männer Israels um sich versammelt und das Lager im Terebinthental aufgeschlagen. Als sie zum Kampf antraten, stellten sie sich den Philistern gegenüber" },
      { number: 3, text: "am Abhang auf. Am gegenüberliegenden Hang standen die Philister. Dazwischen lag das Tal." },
      { number: 4, text: "Da trat ein Vorkämpfer aus den Reihen der Philister heraus. Er hieß Goliat und stammte aus Gat. Er war etwa drei Meter* groß.", footnotes: ["drei Meter. Wörtlich: 6 Ellen und eine Spanne."] },
      { number: 5, text: "Sein Helm und sein Schuppenpanzer waren aus Bronze. Letzterer wog fast 58 Kilogramm*.", footnotes: ["58 Kilogramm. Wörtlich: 5000 Schekel = 57,5 kg, wenn der Schekel 11,5 g wog, wie man aus gefundenen Gewichten entnehmen kann."] },
      { number: 6, text: "Aus Bronze waren auch seine Beinschienen und sein Langschwert, das er über die Schulter gehängt hatte." },
      { number: 7, text: "Der Schaft seines Spießes war wie ein Weberbaum*, und seine Spitze wog fast sieben Kilogramm* und war aus Eisen. Vor ihm her ging der Schildträger.", footnotes: ["Weberbaum. So heißen die Querstangen an den beiden Enden des Webstuhls, an denen die Kettfäden befestigt wurden. Sie mussten eine beträchtliche Dicke haben.", "sieben Kilogramm. Wörtlich: 600 Schekel."] },
      { number: 8, text: "So trat er hin und rief zu den Reihen der Israeliten hinüber: \"Warum stellt ihr euch in Schlachtordnung auf? Ich stehe für die Philister, und ihr seid die Diener Sauls. Bestimmt einen von euch, dass er zu mir herunterkommt!" },
      { number: 9, text: "Wenn er imstande ist, mit mir zu kämpfen und mich zu töten, dann werden wir eure Sklaven. Wenn ich ihn aber besiege und ihn töte, müsst ihr unsere Sklaven werden und uns dienen." },
      { number: 10, text: "Ja, ich mache die Reihen Israels heute lächerlich!\", rief er. \"Schickt mir einen Mann, dann wollen wir miteinander kämpfen!\"" },
      { number: 11, text: "Als Saul und die Männer Israels den Philister so reden hörten, verloren sie den Mut und bekamen große Angst." },
      { number: 12, text: "David war also ein Sohn jenes Efratiters* aus Bethlehem in Juda, der insgesamt acht Söhne hatte und Isai hieß. Dieser war in der Zeit Sauls für den Kriegsdienst schon zu alt.", footnotes: ["Efratiter. So nannte man die Einwohner von Bethlehem, das früher Efrata hieß (1. Mose 35,19)."] },
      { number: 13, text: "Aber seine drei ältesten Söhne Eliab, Abinadab und Schamma waren mit Saul in den Krieg gezogen." },
      { number: 14, text: "David war sein Jüngster, und nur die drei Ältesten waren Saul gefolgt." },
      { number: 15, text: "David ging ab und zu von Saul weg, um die Schafe seines Vaters in Bethlehem zu weiden." },
      { number: 16, text: "Der Philister kam jeden Morgen und Abend und stellte sich kampfbereit hin, vierzig Tage lang." },
      { number: 17, text: "Eines Tages sagte Isai zu David: \"Geh zu deinen Brüdern ins Lager und bring ihnen schnell dieses Getreidemaß* voll gerösteter Körner und zehn Brote.", footnotes: ["Getreidemaß. Wörtlich: Efa = 16-17 kg Getreidekörner."] },
      { number: 18, text: "Nimm auch die zehn Käse hier für den Obersten über Tausend mit. Erkundige dich, wie es deinen Brüdern geht, und bring ein Pfand von ihnen mit!" },
      { number: 19, text: "Sie stehen mit Saul und allen Männern Israels im Terebinthental und sind im Kampf mit den Philistern.\"" },
      { number: 20, text: "David brach früh am Morgen auf. Die Herde überließ er einem Hüter. Er packte die Sachen und machte sich auf den Weg, wie Isai es ihm aufgetragen hatte. Als er zum Lager kam, stellte sich das Heer gerade zum Kampf auf und brüllte den Schlachtruf." },
      { number: 21, text: "Die Schlachtreihen der Israeliten und der Philister standen sich gegenüber." },
      { number: 22, text: "David ließ sein Gepäck bei der Lagerwache und lief in die Schlachtreihe. Als er zu seinen Brüdern kam, fragte er sie nach ihrem Wohlergehen." },
      { number: 23, text: "Während er noch mit ihnen sprach, trat Goliat aus Gat, der Vorkämpfer der Philister, wieder vor. Er sagte das Gleiche wie zuvor, und David hörte es." },
      { number: 24, text: "Als die Männer Israels den Mann sahen, bekamen sie große Angst und wichen vor ihm zurück." },
      { number: 25, text: "\"Habt ihr gesehen, wie er heraufkommt?\", riefen sie einander zu. \"Und wie er Israel verhöhnt! Wer ihn tötet, wird vom König reich belohnt. Er bekommt seine Tochter zur Frau, und seine ganze Familie wird von allen Abgaben befreit.\"" },
      { number: 26, text: "David erkundigte sich bei den Männern, die dort standen: \"Welche Belohnung bekommt der, der diesen Philister da erschlägt und die Schande von Israel nimmt? Dieser unbeschnittene Philister darf doch nicht das Heer des lebendigen Gottes verhöhnen!\"" },
      { number: 27, text: "Sie erklärten ihm noch einmal die Belohnung." },
      { number: 28, text: "Sein ältester Bruder Eliab hörte, wie er mit den Männern redete, und wurde zornig auf ihn. \"Was hast du überhaupt hier zu suchen? Wem hast du unsere paar Schafe in der Wildnis überlassen? Ich weiß genau, wie hochnäsig und eitel du im Grunde deines Herzens bist! Du bist nur hergekommen, um einmal dem Kampf zuzuschauen!\"" },
      { number: 29, text: "David erwiderte: \"Was habe ich denn getan? Ich frage doch nur.\"" },
      { number: 30, text: "Er drehte sich zu einem anderen um und wiederholte die Frage. Und wieder bekam er dieselbe Antwort." },
      { number: 31, text: "Es sprach sich herum, was David gefragt hatte. Man berichtete es auch Saul, und der ließ ihn gleich zu sich rufen." },
      { number: 32, text: "\"Niemand soll den Mut wegen dieses Philisters sinken lassen\", sagte David zu Saul. \"Dein Diener wird hingehen und mit ihm kämpfen.\"" },
      { number: 33, text: "Aber Saul erwiderte: \"Das kannst du nicht! Du bist ein junger Mann, und er ist von Jugend an im Kampf erprobt.\"" },
      { number: 34, text: "Da sagte David: \"Dein Diener hütete die Schafe für seinen Vater. Wenn dann ein Löwe oder Bär kam und ein Lamm aus der Herde packte," },
      { number: 35, text: "lief ich ihm nach, schlug auf ihn ein und riss es aus seinem Rachen. Wenn er mich dann angriff, packte ich ihn am Bart und schlug ihn tot." },
      { number: 36, text: "So hat dein Diener Löwen und Bären erschlagen. Diesem unbeschnittenen Philister soll es genauso ergehen wie einem von ihnen. Denn er hat das Heer des lebendigen Gottes verhöhnt." },
      { number: 37, text: "Und Jahwe\", fuhr David fort, \"der mich aus den Klauen von Löwen und Bären gerettet hat, wird mich auch aus der Hand dieses Philisters retten!\" – \"Gut\", sagte Saul, \"dann geh! Jahwe sei mit dir!\"" },
      { number: 38, text: "Saul gab David seine eigene Rüstung, zog ihm den Brustpanzer an und setzte ihm einen Bronzehelm auf." },
      { number: 39, text: "David hängte sich Sauls Schwert über die Rüstung und machte ein paar Schritte. Doch er war es nicht gewohnt. \"Ich kann darin nicht gehen\", sagte er zu Saul. \"Ich habe es noch nie versucht.\" Dann legte er alles wieder ab." },
      { number: 40, text: "Er nahm seinen Hirtenstab, suchte fünf glatte Steine aus dem Bach und steckte sie in seine Hirtentasche, die ihm als Schleudersteintasche diente. Dann nahm er seine Schleuder in die Hand und ging dem Philister entgegen." },
      { number: 41, text: "Auch der Philister kam David immer näher. Sein Schildträger ging vor ihm her." },
      { number: 42, text: "Als er sah, wer ihm da entgegenkam, verachtete er ihn. David war noch ein junger Mann, rotblond, und sah gut aus." },
      { number: 43, text: "Aber der Philister brüllte: \"Bin ich denn ein Hund, dass du mit Stöcken zu mir kommst?\" und verfluchte David im Namen seiner Götter." },
      { number: 44, text: "\"Komm nur her\", sagte er, \"dass ich dein Fleisch den Vögeln und den wilden Tieren vorwerfe!\"" },
      { number: 45, text: "David rief zurück: \"Du kommst zu mir mit Kurzschwert, Spieß und Langschwert. Ich aber komme zu dir im Namen Jahwes, des Allmächtigen, des Gottes der Heere Israels, den du verhöhnt hast." },
      { number: 46, text: "Jahwe wird dich heute in meine Hand geben. Ich werde dich erschlagen und dir den Kopf abhauen. Und die Leichen des Philisterheers werde ich heute noch den Vögeln und den wilden Tieren zum Fraß vorwerfen. Die ganze Welt soll erkennen, dass Israel einen Gott hat." },
      { number: 47, text: "Und diese ganze Menge hier soll sehen, dass Jahwe weder Schwert noch Spieß braucht, um sein Volk zu retten. Denn Jahwe bestimmt den Kampf, und er wird euch in unsere Hände geben.\"" },
      { number: 48, text: "Der Philister kam David immer näher, und auch David lief auf ihn zu." },
      { number: 49, text: "Dann griff er in seine Hirtentasche, holte einen Stein heraus, schleuderte ihn und traf den Philister an der Stirn. Der Stein drang in die Stirn ein, und der Philister stürzte vornüber auf die Erde." },
      { number: 50, text: "So besiegte David mit Schleuder und Stein den Philister. Er hatte kein Schwert in der Hand." },
      { number: 51, text: "Da lief er zu dem Philister hin, zog dessen Schwert aus der Scheide und hieb ihm den Kopf damit ab.Als die Philister sahen, dass ihr stärkster Mann tot war, liefen sie davon." },
      { number: 52, text: "Die Männer von Israel und Juda aber stimmten das Kriegsgeschrei an und verfolgten sie bis in die Niederung hinein und an die Tore von Ekron. Auf dem ganzen Weg von Schaarajim* bis nach Gat und Ekron lagen die Leichen der Philister.", footnotes: ["Schaarajim war eine Stadt im Hügelland von Juda, 17 km nordöstlich von Lachisch."] },
      { number: 53, text: "Dann kehrten die Israeliten zurück und plünderten ihr Lager." },
      { number: 54, text: "David nahm den Kopf des Philisters und brachte ihn nach Jerusalem*. Seine Waffen bewahrte er in seinem Zelt auf.", footnotes: ["Jerusalem war zu dieser Zeit von den Israeliten noch nicht erobert. Entweder hat David die Trophäe nach der Eroberung in die Stadt gebracht oder er hatte sie schon damals als Warnung vor der Stadt aufgestellt."] },
      { number: 55, text: "Saul hatte zugesehen, wie David dem Philister entgegenging, und seinen Heerführer Abner gefragt: \"Wessen Sohn ist doch dieser junge Mann, Abner?\" – \"So wahr du lebst, mein König, ich weiß es nicht\", erwiderte dieser." },
      { number: 56, text: "\"Dann finde es heraus!\", sagte der König." },
      { number: 57, text: "Als David nach der Tötung des Philisters zurückkehrte, nahm Abner ihn in Empfang und brachte ihn zu Saul. David hatte den Kopf des Philisters noch in der Hand." },
      { number: 58, text: "Saul fragte ihn: \"Aus welcher Familie kommst du, junger Mann?\" – \"Ich bin der Sohn deines Dieners Isai aus Bethlehem\", antwortete David." },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Nach diesem Gespräch fühlte sich Jonatan innerlich stark mit David verbunden. Er gewann ihn so lieb wie sein eigenes Leben.", heading: "Davids Wirken am Hof (18-19)\nDavids Freundschaft mit Jonatan" },
      { number: 2, text: "Saul nahm David von diesem Tag an ganz zu sich und ließ ihn nicht mehr zu seiner Familie zurückkehren." },
      { number: 3, text: "Jonatan schloss einen Freundschaftsbund mit David, weil er ihn lieb hatte wie sein eigenes Leben." },
      { number: 4, text: "Dabei zog er Mantel und Rüstung aus und bekleidete David damit. Er schenkte ihm sogar sein Schwert, seinen Bogen und seinen Gürtel." },
      { number: 5, text: "David zog für Saul in den Kampf und hatte bei allem, was dieser ihm auftrug, Erfolg. Saul setzte ihn an die Spitze seiner Truppe. Er war beim ganzen Volk beliebt, auch bei den Dienern Sauls.", heading: "Sauls Eifersucht auf David" },
      { number: 6, text: "Schon als die Männer heimkehrten, nachdem David den Philister erschlagen hatte, zogen Frauen aus allen Städten Israels mit Reigentänzen und Gesang König Saul entgegen. Sie hatten Tamburine und Triangeln bei sich und jubelten ihm zu." },
      { number: 7, text: "Tanzend und singend riefen sie:\"Saul hat tausend Mann erschlagen, / David aber zehnmal tausend.\"" },
      { number: 8, text: "Da wurde Saul ganz heiß vor Zorn, denn diese Worte missfielen ihm sehr. \"David haben sie Zehntausende gegeben und mir nur Tausende\", sagte er, \"jetzt fehlt ihm nur noch das Königtum.\"" },
      { number: 9, text: "Seit diesem Tag blickte Saul mit Argwohn auf David." },
      { number: 10, text: "Am nächsten Tag geriet der böse Geist, den Gott geschickt hatte, über Saul und er fing an, in seinem Haus zu weissagen. David begann wie gewöhnlich auf der Zither zu spielen. Plötzlich hatte Saul einen Speer in der Hand" },
      { number: 11, text: "und warf ihn nach David. Er wollte ihn an die Wand spießen. Doch David wich ihm zweimal aus." },
      { number: 12, text: "Da begann Saul sich vor David zu fürchten, weil Jahwe auf dessen Seite stand. Ihn aber hatte er verlassen." },
      { number: 13, text: "Darum entfernte er David aus seiner Umgebung und machte ihn zum Befehlshaber einer Tausendschaft. An ihrer Spitze unternahm David seine Streifzüge." },
      { number: 14, text: "Bei allen Unternehmungen hatte er Erfolg, denn Jahwe stand ihm bei." },
      { number: 15, text: "Als Saul den großen Erfolg sah, bekam er Angst vor ihm." },
      { number: 16, text: "Aber in ganz Israel und Juda war David beliebt, denn er zog bei allen Streifzügen voran." },
      { number: 17, text: "Saul sagte zu David: \"Pass auf! Ich bin bereit, dir meine älteste Tochter Merab zur Frau zu geben. Dafür sollst du mir als tapferer Kämpfer dienen und die Kriege führen, die Jahwe befiehlt!\" Im Stillen dachte er: \"Ich selbst will mich nicht an ihm vergreifen. Das sollen die Philister tun!\"" },
      { number: 18, text: "David erwiderte: \"Wer bin ich schon, dass ich Schwiegersohn des Königs werden soll? Und was hat meine Familie und die Sippe meines Vaters in Israel schon zu bedeuten?\"" },
      { number: 19, text: "Als es dann aber so weit war, dass Merab, die Tochter Sauls, mit David verheiratet werden sollte, wurde sie stattdessen Adriël aus Mehola* zur Frau gegeben.", footnotes: ["Mehola. Wahrscheinlich ist Abel-Mehola gemeint, 25 km nordöstlich von Sichem."] },
      { number: 20, text: "Aber Michal, Sauls jüngere Tochter, liebte David. Als man Saul davon berichtete, kam ihm das gerade recht." },
      { number: 21, text: "Er sagte sich: \"Ich will sie ihm geben, damit sie zur Falle für ihn wird und er den Philistern in die Hände fällt.\" Zu David sagte er: \"Ich biete dir heute noch einmal an, mein Schwiegersohn zu werden.\"" },
      { number: 22, text: "Er hatte seine Leute angewiesen, David heimlich folgende Botschaft zuzuspielen: \"Du weißt, dass der König große Stücke auf dich hält und auch alle seine Diener haben dich gern. Willst du nicht sein Schwiegersohn werden?\"" },
      { number: 23, text: "Die Leute Sauls redeten in diesem Sinn mit David, aber der sagte: \"Bedeutet es euch so wenig, Schwiegersohn des Königs zu sein? Ich bin nur ein armer und geringer Mann.\"" },
      { number: 24, text: "Die Männer meldeten es Saul," },
      { number: 25, text: "und dieser wies sie an, David beizubringen: \"Der König will keine andere Heiratsgabe als die Vorhäute von 100 Philistern, um sich so an seinen Feinden zu rächen.\" Saul hoffte nämlich, dass David im Kampf gegen die Philister umkommen würde." },
      { number: 26, text: "Als die Diener das Angebot Sauls David überbrachten, war es ihm recht, auf diese Weise Sauls Schwiegersohn zu werden. Und noch war Zeit." },
      { number: 27, text: "David brach mit seinen Leuten auf und erschlug 200 Philister. Er kehrte mit deren Vorhäuten zurück und lieferte sie dem König vollzählig ab, um dessen Schwiegersohn werden zu können. Da gab Saul ihm seine Tochter Michal zur Frau." },
      { number: 28, text: "Saul sah und wusste jetzt, dass Jahwe auf der Seite Davids stand und dass Michal, seine Tochter, ihn liebte." },
      { number: 29, text: "Da fürchtete er sich noch mehr vor David und wurde für immer zu seinem Feind." },
      { number: 30, text: "Die Fürsten der Philister zogen immer wieder gegen Israel. Aber sooft es zum Kampf kam, hatte David mehr Erfolg als alle anderen Heerführer Sauls. Sein Name wurde sehr berühmt." },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Saul sprach vor seinem Sohn Jonatan und seinen Dienern offen davon, David zu töten. Doch Jonatan hatte David lieb gewonnen", heading: "Saul versucht David zu töten" },
      { number: 2, text: "und warnte ihn: \"Mein Vater will dich umbringen\", sagte er. \"Nimm dich morgen früh in acht und bleib im Versteck!" },
      { number: 3, text: "Ich werde mit meinem Vater hinausgehen und auf dem Gelände, wo du bist, neben ihm stehen. Dann werde ich mit ihm über dich reden. Wenn ich etwas herausbekomme, werde ich es dir berichten.\"" },
      { number: 4, text: "Jonatan setzte sich bei seinem Vater für David ein und sagte: \"Der König soll doch wegen seinem Diener David keine Schuld auf sich laden! Er hat dir ja nichts getan, im Gegenteil: Seine Taten nützen dir sehr!" },
      { number: 5, text: "Er hat sein Leben aufs Spiel gesetzt und den Philister erschlagen. Durch ihn hat Jahwe Israel einen großen Sieg verschafft. Du hast es selbst gesehen und dich darüber gefreut. Warum willst du dich schuldig machen und einen Unschuldigen ohne Grund umbringen?\"" },
      { number: 6, text: "Saul hörte auf Jonatan und schwor: \"So wahr Jahwe lebt: Er soll nicht getötet werden!\"" },
      { number: 7, text: "Da rief Jonatan David und erzählte ihm alles. Dann brachte er ihn zu Saul, und David diente Saul wie früher." },
      { number: 8, text: "Es kam wieder zum Kampf mit den Philistern. David zog gegen sie aus und brachte ihnen eine schwere Niederlage bei, sodass sie vor ihm flohen." },
      { number: 9, text: "Da kam der böse Geist, den Jahwe geschickt hatte, wieder über Saul. Er saß gerade in seinem Haus und hatte den Speer in der Hand. David spielte ein Saiteninstrument vor ihm." },
      { number: 10, text: "Da versuchte Saul, David mit dem Speer an die Wand zu spießen. Doch David konnte ausweichen, sodass der Speer in die Wand stieß. David floh und konnte sich in dieser Nacht retten." },
      { number: 11, text: "Da schickte Saul Wachtposten zu Davids Haus, um ihn am nächsten Morgen töten zu lassen. Doch Michal hatte David gewarnt: \"Wenn du dich nicht heute Nacht in Sicherheit bringst, bist du morgen früh tot.\"" },
      { number: 12, text: "So ließ sie David durchs Fenster hinab, dass er fliehen und entkommen konnte." },
      { number: 13, text: "Dann legte sie die Schnitzfigur des Hausgottes aufs Bett, bedeckte sie mit einem Tuch und packte ein Geflecht aus Ziegenhaar ans Kopfende." },
      { number: 14, text: "Als nun Sauls Leute kamen, um David zu holen, sagte sie zu ihnen: \"Er ist krank.\"" },
      { number: 15, text: "Da schickte Saul die Männer noch einmal zu David und sagte: \"Dann bringt ihn eben samt Bett zu mir, damit ich ihn töten kann!\"" },
      { number: 16, text: "Als sie hineinkamen, fanden sie die Götterfigur mit dem Geflecht aus Ziegenhaar in Davids Bett." },
      { number: 17, text: "Saul stellte Michal zur Rede: \"Warum hast du mich so hintergangen und meinen Feind entkommen lassen?\" – \"Er hat gedroht, mich zu töten, wenn ich ihn nicht gehen lasse\", erwiderte sie." },
      { number: 18, text: "Durch seine Flucht hatte David sich in Sicherheit gebracht. Er kam zu Samuel nach Rama und berichtete ihm alles, was Saul ihm angetan hatte. Dann ging er mit ihm zur Prophetensiedlung und blieb dort." },
      { number: 19, text: "Saul wurde gesagt: \"Pass auf! David hält sich in der Prophetensiedlung auf.\"" },
      { number: 20, text: "Da schickte Saul Männer los, die David festnehmen sollten. Als diese aber die Gesellschaft der weissagenden Propheten sahen und Samuel, der an ihrer Spitze stand, kam der Geist Gottes auch über die Männer Sauls, sodass sie ebenfalls weissagten*.", footnotes: ["weissagten. Siehe 1. Samuel 10,5!"] },
      { number: 21, text: "Als man es Saul berichtete, schickte er noch einmal andere los. Doch auch die begannen zu weissagen. Da schickte Saul ein drittes Mal Leute. Doch denen erging es nicht anders." },
      { number: 22, text: "Nun machte sich Saul selbst auf den Weg nach Rama. Als er an die große Zisterne in Sechu kam, erkundigte er sich nach Samuel und David. \"Sie halten sich in der Prophetensiedlung von Rama auf\", sagte man ihm." },
      { number: 23, text: "Schon auf dem Weg dorthin kam der Geist Gottes auch über ihn. Er weissagte im Gehen, bis er in der Prophetensiedlung ankam." },
      { number: 24, text: "Dann warf er auch noch seine Oberkleider ab und weissagte vor Samuel, bis er erschöpft zu Boden fiel. Den ganzen Tag und die folgende Nacht lag er so entblößt auf der Erde. Daher sagt man: \"Ist denn auch Saul unter den Propheten?\"" },
    ] },
    { number: 20, verses: [
      { number: 1, text: "David flüchtete aus der Prophetensiedlung von Rama und kam zu Jonatan. \"Was habe ich nur getan?\", fragte er ihn. \"Was ist meine Schuld? Was wirft dein Vater mir vor, dass er mich umbringen will?\"", heading: "Davids Verhalten als Flüchtling (20-31)\nJonatans Freundschaft" },
      { number: 2, text: "\"Das wird auf keinen Fall geschehen\", erwiderte Jonatan. \"Du wirst nicht sterben. Sieh doch, mein Vater sagt mir immer, was er vorhat, Großes und auch Kleines. Warum sollte mein Vater ausgerechnet diese Sache vor mir verheimlichen? Es ist nicht so, wie du denkst!\"" },
      { number: 3, text: "Doch David widersprach: \"Dein Vater weiß genau, dass ich deine Gunst gewonnen habe. Deshalb denkt er: 'Jonatan soll das nicht wissen, denn es könnte ihn schmerzen.' So wahr Jahwe lebt und so gewiss du lebst: Es war nur ein Schritt zwischen mir und dem Tod!\"" },
      { number: 4, text: "Jonatan fragte: \"Was willst du? Was kann ich für dich tun?\"" },
      { number: 5, text: "Da sagte David: \"Morgen ist Neumondstag, da erwartet mich der König eigentlich an seinem Tisch. Lass mich gehen, dass ich mich in der Umgebung bis übermorgen Abend verstecke." },
      { number: 6, text: "Sollte dein Vater mich vermissen, dann sag zu ihm: 'David hat mich dringend gebeten, in seine Vaterstadt Bethlehem laufen zu dürfen. Dort wird für seine ganze Familie das jährliche Opferfest gefeiert.'" },
      { number: 7, text: "Wenn dein Vater sagt: 'Es ist gut', dann droht mir keine Gefahr. Wenn er aber zornig wird, weißt du, dass er Böses beschlossen hat." },
      { number: 8, text: "Erweise deinem Diener doch diese Gunst! Denn du hast deinen Diener in einen Bund Jahwes mit dir treten lassen. Wenn ich aber wirklich schuldig bin, dann töte du mich! Warum willst du mich erst deinem Vater ausliefern?\"" },
      { number: 9, text: "Jonatan erwiderte: \"Wie kannst du mir so etwas nur zutrauen? Warum sollte ich es dir nicht sagen, wenn ich sicher weiß, dass mein Vater dir Böses antun will?\"" },
      { number: 10, text: "\"Und wer wird mir die Nachricht bringen, wenn dein Vater dir eine harte Antwort gibt?\", fragte David." },
      { number: 11, text: "\"Komm, wir gehen nach draußen\", sagte Jonatan zu ihm. Während sie miteinander gingen," },
      { number: 12, text: "sagte er: \"Vor Jahwe, dem Gott Israels, verspreche ich dir: Ich werde meinen Vater morgen oder übermorgen um diese Zeit aushorchen. Wenn ich feststelle, dass es gut um David steht und ich dir keine Nachricht schicken sollte," },
      { number: 13, text: "dann möge Jahwe mir dies und jenes antun! Wenn mein Vater aber wirklich deinen Tod beschlossen hat, dann werde ich es dir persönlich mitteilen und dich ziehen lassen, damit du dich in Sicherheit bringen kannst. Und Jahwe möge mit dir sein, wie er mit meinem Vater gewesen ist." },
      { number: 14, text: "Und nicht wahr, solange ich lebe, wirst du mich die Güte Jahwes spüren lassen, dass ich nicht sterben muss?" },
      { number: 15, text: "Entziehe auch meiner Familie niemals deine Gunst, auch dann nicht, wenn Jahwe die Feinde Davids Mann für Mann beseitigen wird.\"" },
      { number: 16, text: "So schloss Jonatan einen Bund mit David und seiner Familie. Er sagte: \"Möge Jahwe Davids Feinde zur Rechenschaft ziehen!\"" },
      { number: 17, text: "Jonatan ließ nun auch David bei seiner Liebe zu ihm schwören, denn er liebte ihn wie sein eigenes Leben." },
      { number: 18, text: "Dann sagte Jonatan zu David: \"Morgen am Neumondstag wird man dich vermissen, weil dein Platz leer bleibt." },
      { number: 19, text: "Warte bis übermorgen und komm dann schnell herunter an die Stelle, wo du dich schon einmal* versteckt hast, und bleib bei dem Steinhaufen dort.", footnotes: ["schon einmal. Wörtlich: am Tag der Tat. Siehe 1. Samuel 19,1-3!"] },
      { number: 20, text: "Ich werde drei Pfeile nach dieser Seite schießen und so tun, als wollte ich ein Ziel treffen." },
      { number: 21, text: "Dann werde ich den Jungen schicken, die Pfeile zu suchen. Wenn ich ihm dann nachrufe: 'Pass auf, die Pfeile liegen näher bei mir!', dann kannst du hervorkommen, denn es steht gut um dich. Du bist nicht in Gefahr, so wahr Jahwe lebt." },
      { number: 22, text: "Wenn ich aber zu dem Jungen sage: 'Pass auf! Die Pfeile liegen weiter weg!', dann geh, denn Jahwe schickt dich weg!" },
      { number: 23, text: "Für das, was wir miteinander geredet haben, soll Jahwe für alle Zeiten Zeuge zwischen mir und dir sein!\"" },
      { number: 24, text: "David versteckte sich im Gelände. Am Neumondstag setzte sich der König an die Festtafel." },
      { number: 25, text: "Er saß auf seinem Platz an der Wand, wo er sich immer hinsetzte. Als Jonatan einmal aufstand, saß nur noch Abner an der Seite Sauls. Davids Platz blieb leer." },
      { number: 26, text: "Saul sagte an diesem Tag nichts, denn er dachte: \"Es wird etwas vorgefallen sein, dass er den Reinheitsvorschriften nicht genügen kann.\"" },
      { number: 27, text: "Als aber der Platz auch am zweiten Festtag leer war, fragte er Jonatan: \"Warum ist der Sohn Isais gestern und heute nicht zum Essen gekommen?\"" },
      { number: 28, text: "Jonatan erwiderte: \"David hat mich dringend gebeten, nach Bethlehem gehen zu dürfen." },
      { number: 29, text: "Er sagte: 'Lass mich doch gehen! Wir haben ein Opferfest für die ganze Familie in der Stadt, und mein Bruder hat darauf bestanden, dass ich komme. Wenn ich deine Gunst gefunden habe, dann lass mich doch gehen, dass ich meine Brüder wiedersehe!' Deshalb ist er nicht zum Tisch des Königs gekommen.\"" },
      { number: 30, text: "Da packte Saul der Zorn und er schrie Jonatan an: \"Du elender Bastard!* Ich weiß genau, dass du zu diesem Sohn Isais hältst zu deiner Schande und zur Scham und Schande deiner Mutter!", footnotes: ["elender Bastard. Wörtlich: Sohn einer widerspenstigen Hure!"] },
      { number: 31, text: "Denn so lange der Sohn Isais lebt, wirst du ganz sicher keinen Bestand haben, weder du, noch dein Königtum. Schick also hin und lass ihn zu mir bringen; er ist ein Kind des Todes!\"" },
      { number: 32, text: "Doch Jonatan erwiderte seinem Vater: \"Warum soll er sterben? Was hat er denn getan?\"" },
      { number: 33, text: "Da schleuderte Saul den Speer nach ihm. Er wollte ihn durchbohren. Nun wusste Jonatan, dass sein Vater fest entschlossen war, David zu töten." },
      { number: 34, text: "Glühend vor Zorn stand er vom Tisch auf und aß an diesem zweiten Tag des Neumondfestes keinen Bissen mehr. Er war traurig wegen David, und es tat ihm weh, dass sein Vater ihn so beschimpft hatte." },
      { number: 35, text: "Am nächsten Morgen ging Jonatan mit einem jungen Diener zu der Stelle, wo er sich mit David verabredet hatte." },
      { number: 36, text: "Er sagte zu dem Jungen: \"Lauf und such die Pfeile, die ich abschieße!\" Während der Junge loslief, schoss er den Pfeil über ihn hinweg." },
      { number: 37, text: "Als er an die Stelle kam, wo der Pfeil niedergegangen war, rief Jonatan ihm nach: \"Liegt der Pfeil nicht noch weiter von dir weg?" },
      { number: 38, text: "Los, beeile dich und bleib nicht stehen!\" Der Junge hob den Pfeil auf und brachte ihn zu seinem Herrn zurück." },
      { number: 39, text: "Er wusste aber von nichts, nur Jonatan und David wussten um die Sache." },
      { number: 40, text: "Dann gab Jonatan dem Jungen seine Waffen und sagte: \"Geh, bring sie in die Stadt!\"" },
      { number: 41, text: "Als er gegangen war, kam David aus seinem Versteck hinter dem Steinhaufen vor. Er kniete sich vor Jonatan hin und beugte sich dreimal zur Erde nieder. Dann küssten sie einander und weinten einer über den anderen. David weinte immer noch heftig," },
      { number: 42, text: "als Jonatan zu ihm sagte: \"Geh in Frieden! Was wir beide im Namen Jahwes geschworen haben, dafür sei Jahwe Zeuge zwischen uns und zwischen unseren Nachkommen.\"" },
    ] },
    { number: 21, verses: [
      { number: 1, text: "David machte sich rasch auf den Weg, und Jonatan kehrte in die Stadt zurück.", heading: "David bei den Priestern in Nob" },
      { number: 2, text: "Auf seiner Flucht kam David nach Nob* zum Priester Ahimelech. Dieser lief ihm aufgeregt entgegen und fragte: \"Warum kommst du allein? Weshalb ist niemand bei dir?\"", footnotes: ["Nob. Die Stadt lag wahrscheinlich 2,5 km nordöstlich von Jerusalem. Nach der Zerstörung von Schilo (Jeremia 7,12) war das Zelt der Gottesbegegnung dort aufgebaut worden."] },
      { number: 3, text: "David erwiderte: \"Der König hat mir einen Auftrag gegeben, von dem niemand etwas erfahren darf. Die Leute habe ich an einen bestimmten Ort bestellt." },
      { number: 4, text: "Aber jetzt: Hast du etwas zur Hand? Kannst du mir fünf Brotfladen geben oder was sich sonst auftreiben lässt?\"" },
      { number: 5, text: "\"Ich habe aber kein gewöhnliches Brot hier, nur heiliges Brot ist da\", wandte der Priester ein. \"Wenn sich deine Männer nur von Frauen ferngehalten haben!\"" },
      { number: 6, text: "\"Seit vorgestern sind wir mit keiner Frau in Berührung gekommen\", sagte David. \"Seit unserem Aufbruch sind auch die Waffen der Leute rein*. Auch wenn es nur ein gewöhnliches Unternehmen ist, so werden sie heute erst recht rein sein.\"", footnotes: ["rein. Das meint hier rein von Blut und rein im kultischen Sinn. Siehe auch Markus 2,25-26."] },
      { number: 7, text: "Da gab der Priester ihm die heiligen Brote, die man eben vom Tisch im Heiligtum abgeräumt hatte, um frisches Brot aufzulegen. Andere Brote waren nicht da." },
      { number: 8, text: "An diesem Tag hielt sich dort vor Jahwe auch ein Mann aus dem Gefolge Sauls auf. Es war der Aufseher über die Hirten Sauls, er hieß Doëg und war ein Edomiter." },
      { number: 9, text: "David fragte Ahimelech: \"Hast du nicht einen Speer oder ein Schwert für mich? Ich konnte meine Waffen nicht mitnehmen, weil die Sache des Königs so dringend war.\"" },
      { number: 10, text: "\"Doch\", sagte der Priester, \"wir haben das Schwert des Philisters Goliat hier, den du im Terebinthental erschlagen hast. Es ist in einen Mantel gewickelt und liegt hinter dem Efod*. Wenn du willst, kannst du es haben. Eine andere Waffe ist nicht hier.\" – \"Gib es mir!\", sagte David. \"Solch ein Schwert gibt es nicht noch einmal.\"", footnotes: ["Efod. Siehe 1. Samuel 2,18!"] },
      { number: 11, text: "Noch am selben Tag setzte David seine Flucht fort und kam zu Achisch, dem König von Gat.", heading: "David bei Achisch von Gat" },
      { number: 12, text: "Doch die Hofbeamten des Achisch warnten den König: \"Ist das nicht David? Er ist doch der König im Land. Er ist es doch, von dem sie in Reigentänzen singen:'Saul hat tausend Mann erschlagen, / David aber zehnmal tausend.'\"" },
      { number: 13, text: "David nahm sich diese Worte sehr zu Herzen und geriet in große Furcht vor Achisch, dem König von Gat." },
      { number: 14, text: "Darum stellte er sich wahnsinnig und tobte, als man ihn festhalten wollte. Er kritzelte auf die Torflügel und ließ Speichel in seinen Bart laufen." },
      { number: 15, text: "Da sagte Achisch zu seinen Leuten: \"Ihr seht doch, dass der Mann wahnsinnig ist! Was bringt ihr ihn zu mir?" },
      { number: 16, text: "Gibt es hier nicht schon genug Verrückte, dass ihr mir auch noch den herbeischaffen müsst? Soll er sich doch woanders austoben, aber nicht in meinem Haus!\"" },
    ] },
    { number: 22, verses: [
      { number: 1, text: "David floh aus Gat in eine Höhle bei Adullam*. Als seine Brüder und seine ganze Sippe davon hörten, kamen sie dort zu ihm hin.", heading: "David findet Schicksalsgenossen", footnotes: ["Adullam, \"Schlupfwinkel\", Stadt in der Schefela, dem Hügelland von Juda, 26 km westlich von Jerusalem."] },
      { number: 2, text: "Bald scharten sich noch andere um ihn: Menschen, die bedrängt, verschuldet oder verbittert waren. Er wurde ihr Anführer. Schließlich waren es etwa 400 Mann." },
      { number: 3, text: "Von dort aus ging David nach Mizpe* in Moab und bat den König der Moabiter: \"Lass doch meinen Vater und meine Mutter bei euch wohnen, bis ich weiß, was Gott mit mir vorhat!\"", footnotes: ["Mizpe. \"Wachtturm\". Die genaue Lage dieses Ortes ist unbekannt."] },
      { number: 4, text: "So brachte er beide zum König von Moab. Solange David auf der Bergfestung war, blieben sie am Königshof." },
      { number: 5, text: "Dann sagte der Prophet Gad zu David: \"Bleib nicht auf der Bergfestung! Kehr ins Land Juda zurück!\" Da zog David in den Wald von Heret*.", footnotes: ["Heret. Die Lage des Waldes ist unbekannt, vielleicht westlich oder südwestlich von Jerusalem."] },
      { number: 6, text: "Saul erfuhr, dass David und seine Männer entdeckt worden waren. Er saß gerade auf der Anhöhe bei Gibea unter der Tamariske* und hatte den Speer in der Hand. Sein Gefolge stand um ihn herum.", heading: "Sauls Rache an den Priestern von Nob", footnotes: ["Die Tamariske ist ein reich verzweigter immergrüner Baum, der bis zu 10 Meter hoch wird."] },
      { number: 7, text: "Da sagte er zu ihnen: \"Hört her, ihr Benjaminiten! Wird der Sohn Isais euch wohl Felder und Weinberge geben, wird er euch wohl zu Hauptleuten und Obersten machen?" },
      { number: 8, text: "Oder warum sonst habt ihr euch alle gegen mich verschworen? Keiner von euch hat mir gesagt, dass mein Sohn einen Bund mit dem Sohn Isais geschlossen hat. Keinen von euch kümmert es, dass mein Sohn meinen Sklaven gegen mich aufhetzt, sodass der mich verrät und mir auflauert, wie es jetzt offenbar ist. Warum hat mir das denn keiner gesagt?\"" },
      { number: 9, text: "Da sagte der Edomiter Doëg, der ebenfalls beim Gefolge Sauls stand: \"Ich sah den Sohn Isais, wie er zu Ahimelech Ben-Ahitub nach Nob kam." },
      { number: 10, text: "Der hat Jahwe für ihn befragt, hat ihm Proviant und das Schwert des Philisters Goliat gegeben.\"" },
      { number: 11, text: "Da ließ der König den Priester Ahimelech Ben-Ahitub und seine ganze Verwandtschaft holen, die Priester von Nob. Als sie vor ihm standen," },
      { number: 12, text: "sagte Saul: \"Hör zu, Ben-Ahitub!\" – \"Ich höre, mein Herr\", antwortete dieser." },
      { number: 13, text: "\"Warum habt ihr euch gegen mich verschworen, du und dieser Sohn von Isai?\", fuhr Saul ihn an. \"Du hast ihm Proviant und ein Schwert gegeben und Gott für ihn befragt, sodass er mich verrät und mir auflauert, wie es jetzt offenbar ist.\"" },
      { number: 14, text: "Ahimelech erwiderte dem König: \"Aber David ist doch der treuste Gefolgsmann, den du hast. Er ist Schwiegersohn des Königs, der Anführer deiner Elitetruppe und wird in deinem ganzen Haus geehrt." },
      { number: 15, text: "Es war doch keineswegs das erste Mal, dass ich Gott für ihn befragt habe. Das kann der König seinem Diener doch nicht zur Last legen, und auch nicht meiner Verwandtschaft! Dein Diener hat von allem nicht das Geringste gewusst.\"" },
      { number: 16, text: "Aber der König sagte: \"Du musst sterben, Ahimelech, du und deine ganze Sippschaft!\"" },
      { number: 17, text: "Er befahl den Wachen, die bei ihm standen: \"Umstellt diese Priester Jahwes und tötet sie! Denn auch sie haben sich mit David verbündet. Und sie wussten, dass er auf der Flucht war, und haben es mir nicht gemeldet.\" Aber die Diener des Königs weigerten sich, die Priester Jahwes umzubringen." },
      { number: 18, text: "Da sagte der König zu Doëg: \"Mach du es, und schlag die Priester tot!\" Der Edomiter Doëg tat es. Er fiel über die Priester her und tötete an diesem Tag 85 Männer. Sie hatten alle das leinene Efod getragen." },
      { number: 19, text: "Außerdem ließ Saul alle Einwohner der Priesterstadt Nob mit dem Schwert umbringen: Männer und Frauen, Kinder und Säuglinge, dazu auch Rinder und Esel, Schafe und Ziegen." },
      { number: 20, text: "Es entkam nur ein Sohn von Ahimelech Ben-Ahitub, das war Abjatar. Er floh zu David" },
      { number: 21, text: "und berichtete ihm, dass Saul die Priester Jahwes umgebracht hatte." },
      { number: 22, text: "Da sagte David zu ihm: \"Ich hätte schon an jenem Tag wissen müssen, als ich Doëg in Nob sah, dass er es Saul verraten würde. Ich bin schuld am Tod deiner ganzen Verwandtschaft." },
      { number: 23, text: "Bleib jetzt bei mir und hab keine Angst! Denn der, der es auf dich abgesehen hat, will auch mich umbringen. Bei mir bist du also am sichersten.\"" },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Eines Tages wurde David gemeldet: \"Die Philister führen Krieg gegen Keïla* und rauben das frisch gedroschene Getreide.\"", heading: "David befreit Keïla", footnotes: ["Keïla lag 29 km südwestlich von Jerusalem."] },
      { number: 2, text: "Da fragte David Jahwe: \"Soll ich hinziehen und diese Philister schlagen?\" Jahwe sagte ihm: \"Geh hin, schlag die Philister und befreie Keïla.\"" },
      { number: 3, text: "Aber seine Leute hielten ihm entgegen: \"Wir haben schon hier in Juda Angst und nun sollen wir gar nach Keïla ziehen und die Truppen der Philister angreifen?\"" },
      { number: 4, text: "Da fragte David Jahwe ein zweites Mal und erhielt die Antwort: \"Auf, zieh nach Keïla hinunter. Ich werde die Philister in deine Hände geben.\"" },
      { number: 5, text: "So zog David mit seinen Männern nach Keïla und griff die Philister an. Er trieb ihr Vieh weg, brachte ihnen eine schwere Niederlage bei und befreite die Bewohner der Stadt." },
      { number: 6, text: "Abjatar hatte nämlich das Efod mitgebracht, als er zu David floh und mit ihm nach Keïla zog." },
      { number: 7, text: "Als Saul gemeldet wurde, dass David nach Keïla gekommen war, sagte er: \"Gott hat ihn verworfen und mir ausgeliefert. Jetzt sitzt er in der Falle, denn er ist in eine Stadt mit Mauern und Toren gekommen.\"" },
      { number: 8, text: "Saul rief das ganze Volk zum Kampf gegen Keïla und zur Belagerung der Stadt auf." },
      { number: 9, text: "Als David erfuhr, dass Saul Böses gegen ihn plante, sagte er zum Priester Abjatar: \"Bring das Efod her!\"" },
      { number: 10, text: "Dann sagte er: \"Jahwe, Gott Israels, dein Diener hat die sichere Nachricht bekommen, dass Saul nach Keïla kommen und die Stadt nur deshalb vernichten will, weil ich hier bin." },
      { number: 11, text: "Werden die Bürger von Keïla mich ihm ausliefern? Wird Saul tatsächlich herkommen, wie dein Diener es gehört hat? Jahwe, Gott Israels, lass es deinen Diener doch wissen!\" Jahwe sagte: \"Er wird herabkommen.\"" },
      { number: 12, text: "David fragte weiter: \"Werden die Leute der Stadt mich und meine Männer an ihn ausliefern?\" – \"Sie werden es tun\", sagte Jahwe." },
      { number: 13, text: "Da verließen David und seine Männer Keïla und streiften hin und her durch das Land." },
      { number: 14, text: "David hielt sich hauptsächlich in den natürlichen Bergfestungen der Wüste auf, vor allem im Gebirge der Wüste Sif*. Saul war die ganze Zeit hinter ihm her, aber Gott ließ David nicht in seine Hände fallen.", heading: "David in der Wüste Sif", footnotes: ["Der Ort Sif liegt 8 km südöstlich von Hebron. Die Wüste Sif liegt östlich davon."] },
      { number: 15, text: "David wusste, dass Saul ausgezogen war, um ihn umzubringen. Als er nun in Horescha* war, in der Wüste Sif,", footnotes: ["Horescha lag wahrscheinlich östlich von Sif, 8 km südöstlich von Hebron."] },
      { number: 16, text: "kam Sauls Sohn Jonatan zu ihm und ermutigte ihn, Gott zu vertrauen." },
      { number: 17, text: "\"Hab keine Angst!\", sagte er zu ihm. \"Mein Vater wird dich nicht finden. Du wirst König über Israel werden, und ich werde der zweite Mann nach dir sein. Das weiß auch mein Vater Saul genau.\"" },
      { number: 18, text: "Beide schlossen einen Bund vor Jahwe. Dann kehrte Jonatan nach Hause zurück, während David in Horescha blieb." },
      { number: 19, text: "Einige Leute von Sif kamen zu Saul und sagten: \"David hält sich bei uns in den Bergfestungen versteckt. Er ist jetzt in Horescha, auf dem Hügel Hachila südlich von Jeschimon*.", heading: "David wird verraten", footnotes: ["Jeschimon. Wildnis östlich von Sif."] },
      { number: 20, text: "Der König möge nun kommen, wenn er es will. Wir werden dafür sorgen, dass er dem König in die Hände fällt.\"" },
      { number: 21, text: "\"Jahwe segne euch dafür\", sagte Saul, \"dass ihr Mitleid mit mir hattet!" },
      { number: 22, text: "Geht und erkundet alles noch genauer! Stellt fest, wo er sich aufhält und wer ihn dort gesehen hat! Denn man hat mir gesagt, dass er sehr schlau ist." },
      { number: 23, text: "Passt genau auf und erkundet jeden Schlupfwinkel, in dem er sich versteckt halten könnte! Wenn ihr ganz sicher seid, kommt wieder zu mir. Dann will ich mit euch ziehen. Und wenn er noch im Land ist, werde ich ihn aufspüren, selbst wenn ich ganz Juda durchkämmen müsste.\"" },
      { number: 24, text: "Die Männer gingen Saul voraus nach Sif zurück. David und seine Männer waren in der Wüste Maon, in der Ebene südlich von Jeschimon." },
      { number: 25, text: "Saul zog dann mit seinen Männern los, um David zu suchen. Als dieser davon hörte, wollte er sich in das Felsenversteck in der Wüste Maon zurückziehen. Das wurde Saul gemeldet, und er folgte David in die Wüste hinein." },
      { number: 26, text: "Saul ging an der einen Seite des Berges entlang, David und seine Männer auf der anderen. David versuchte verzweifelt, Saul zu entkommen, während Saul und seine Männer schon dabei waren, ihn zu umzingeln." },
      { number: 27, text: "Da kam ein Bote zu Saul und meldete: \"Die Philister sind ins Land eingefallen!\"" },
      { number: 28, text: "Da brach Saul die Verfolgung ab und zog gegen die Philister. Deshalb nennt man diesen Ort Sela-Machlekot, Trennungsfels." },
    ] },
    { number: 24, verses: [
      { number: 1, text: "David zog sich von dort in die Bergfestungen von En-Gedi* zurück.", heading: "Davids Großmut", footnotes: ["En-Gedi (Ziegenquell) ist eine Oase etwa in der Mitte des Westufers vom Toten Meer. Heute ist es ein Naturschutzgebiet."] },
      { number: 2, text: "Und als Saul von der Verfolgung der Philister zurückgekehrt war, wurde ihm gemeldet: \"David ist jetzt in der Bergwüste bei En-Gedi.\"" },
      { number: 3, text: "Saul nahm 3000 der besten Männer Israels mit und zog auf der Suche nach David auf die Steinbockfelsen zu." },
      { number: 4, text: "Als er an den Schafhürden vorbeikam, ging er zum Austreten in die Höhle dort. Hinten in der Höhle saß David mit seinen Männern." },
      { number: 5, text: "Die flüsterten ihm zu: \"Sieh doch, das ist der Tag, von dem Jahwe dir gesagt hat: Pass auf, ich werde deinen Feind in deine Hände geben, und du kannst mit ihm machen, was du willst.\" Da stand David auf und schnitt heimlich einen Zipfel von Sauls Obergewand ab." },
      { number: 6, text: "Danach aber schlug ihm das Gewissen, weil er das getan hatte." },
      { number: 7, text: "Er sagte zu seinen Männern: \"Jahwe behüte mich davor, dass ich Hand an meinen Herrn, den Gesalbten Jahwes, legen sollte, denn er ist doch der gesalbte König Jahwes!\"" },
      { number: 8, text: "David wies seine Männer zurecht und erlaubte ihnen nicht, sich an Saul zu vergreifen. Als Saul die Höhle wieder verließ, um seinen Weg fortzusetzen," },
      { number: 9, text: "kam David aus der Höhle heraus und rief ihm nach: \"Mein Herr und König!\" Saul drehte sich um, und David fiel auf die Knie und neigte sein Gesicht zur Erde." },
      { number: 10, text: "Er sagte zu Saul: \"Warum hörst du auf das Gerede von Menschen, die behaupten, dass David dich ins Verderben stürzen will?" },
      { number: 11, text: "Heute konntest du dich mit eigenen Augen überzeugen, dass Jahwe dich in der Höhle in meine Hände gegeben hatte. Meine Leute drängten mich, dich umzubringen. Aber ich habe dich verschont, weil ich dachte: 'Ich will mich nicht an meinem Herrn vergreifen, denn er ist der Gesalbte Jahwes!'" },
      { number: 12, text: "Sieh doch, mein Vater, siehst du hier den Zipfel deines Gewands in meiner Hand? Ich hätte dich töten können, aber ich habe nur einen Zipfel deines Obergewands abgeschnitten. Daran siehst du doch, dass ich kein Rebell bin und dir nichts Böses tun will. Ich habe mich nicht an dir versündigt, und doch verfolgst du mich und willst mir das Leben nehmen!" },
      { number: 13, text: "Jahwe soll Richter zwischen uns sein! Er mag mich an dir rächen, aber ich werde meine Hand nicht gegen dich erheben!" },
      { number: 14, text: "Wie das alte Sprichwort sagt: 'Nur Verbrecher begehen Verbrechen.' Aber ich werde dich nicht antasten." },
      { number: 15, text: "Hinter wem ist der König von Israel denn her? Wen verfolgst du denn? Einen toten Hund, einen einzelnen Floh!" },
      { number: 16, text: "Jahwe soll als Richter zwischen dir und mir entscheiden! Er soll meinen Prozess gegen dich führen und mir mein Recht verschaffen!\"" },
      { number: 17, text: "Als David ausgeredet hatte, sagte Saul: \"Ist das wirklich deine Stimme, mein Sohn David?\" Und er begann laut zu weinen." },
      { number: 18, text: "Dann sagte er zu David: \"Du bist gerechter als ich, denn du hast mir Gutes erwiesen, obwohl ich dir Böses angetan habe." },
      { number: 19, text: "Heute hast du es bewiesen, denn Jahwe hatte mich in deine Hand gegeben, und du hast mich nicht umgebracht." },
      { number: 20, text: "Wenn jemand seinen Feind findet, lässt er ihn dann unbehelligt weiterlaufen? Jahwe möge dich für das belohnen, was du heute an mir getan hast!" },
      { number: 21, text: "Jetzt aber – ich weiß ja, dass du König wirst, ja König, und in deiner Hand wird das Königtum Israels festen Bestand haben," },
      { number: 22, text: "jetzt aber schwöre mir bei Jahwe, dass du meine Nachkommen nicht beseitigst und meinen Namen in meiner Sippe nicht auslöschen wirst!\"" },
      { number: 23, text: "David schwor es. Dann kehrte Saul nach Hause zurück. David und seine Männer stiegen auf die Bergfestung." },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Samuel starb. Ganz Israel versammelte sich und trauerte um ihn. Dann begruben sie ihn auf seinem Besitz in Rama. David zog sich damals weiter in Richtung der Wüste Paran* zurück.", heading: "David und Abigajil", footnotes: ["Die Wüste Paran liegt irgendwo im Zentral-Sinai."] },
      { number: 2, text: "In Maon* lebte ein Mann, der sein Gewerbe in Karmel* ausübte. Er befand sich gerade dort, um seine Schafe zu scheren. Der Mann war sehr vermögend, ihm gehörten 3000 Schafe und 1000 Ziegen.", footnotes: ["Maon lag 13 km südlich von Hebron.", "Gemeint ist das Dorf Karmel in Juda, 12 km südöstlich von Hebron."] },
      { number: 3, text: "Er hieß Nabal und war ein Nachkomme Kalebs. Seine Frau hieß Abigajil. Sie war schön und hatte einen klaren Verstand, er selbst aber war grob und gemein." },
      { number: 4, text: "Als David in der Wüste hörte, dass Nabal seine Schafe schor," },
      { number: 5, text: "schickte er zehn junge Männer mit dem Auftrag los: \"Geht nach Karmel hoch und fragt Nabal in meinem Namen nach seinem Wohlergehen." },
      { number: 6, text: "Richtet ihm aus: 'Ich wünsche dir alles Gute! Friede sei mit dir, mit deiner Familie und mit allem, was du besitzt." },
      { number: 7, text: "Ich habe gerade gehört, dass du Schafschur hast. Du weißt doch, dass deine Hirten in unserer Nähe waren und wir ihnen nichts zuleide getan haben. Und während der ganzen Zeit in Karmel ist ihnen nichts abhanden gekommen." },
      { number: 8, text: "Frag deine Leute, sie werden es dir bestätigen. Nimm also meine jungen Leute freundlich auf, denn wir kommen doch zu einem Fest! Gib ihnen mit, was du für deinen Sohn David erübrigen kannst!'\"" },
      { number: 9, text: "Davids junge Leute kamen zu Nabal, richteten ihm alles im Namen Davids aus und warteten dann ab." },
      { number: 10, text: "Aber Nabal entgegnete ihnen: \"David, wer ist das? Der Sohn Isais, wer soll das sein? Heutzutage gibt es viele Knechte, die ihrem Herrn davongelaufen sind." },
      { number: 11, text: "Da soll ich mein Brot und Wasser nehmen und die Tiere, die ich für meine Schafscherer geschlachtet habe, und es Leuten geben, von denen ich nicht einmal weiß, woher sie kommen?\"" },
      { number: 12, text: "Die jungen Männer kehrten zu David zurück und berichteten ihm alles." },
      { number: 13, text: "Da befahl David seinen Männern: \"Schnallt eure Schwerter um!\" Auch er nahm sein Schwert und zog los. 400 Mann folgten ihm, 200 ließ er beim Gepäck." },
      { number: 14, text: "Einer von den Leuten Nabals berichtete Abigajil: \"David hat Boten aus der Wüste zu Nabal geschickt, um unserem Herrn alles Gute zu wünschen, aber er hat sie nur angeschrien." },
      { number: 15, text: "Dabei waren die Männer Davids immer sehr gut zu uns. Sie haben uns nicht belästigt und die ganze Zeit, in der wir in ihrer Nähe waren, haben wir nicht das Geringste vermisst." },
      { number: 16, text: "Sie waren Tag und Nacht wie eine schützende Mauer um uns, solange wir die Herden in ihrer Nähe weideten." },
      { number: 17, text: "Sieh zu, ob du noch etwas tun kannst, sonst ist unser Herr und sein ganzer Haushalt verloren. Er ist ja so boshaft, dass man nicht mit ihm reden kann.\"" },
      { number: 18, text: "Da ließ Abigajil schnell einige Esel beladen. Sie nahm 200 Fladenbrote, zwei Schläuche Wein, fünf zubereitete Schafe, fünf Getreidemaße voll Röstkorn, 100 Rosinenkuchen und 200 Feigenkuchen." },
      { number: 19, text: "Dann sagte sie zu ihren Dienern: \"Geht mit den Eseln voraus, ich komme gleich nach!\" Ihrem Mann aber sagte sie nichts davon." },
      { number: 20, text: "Als sie auf ihrem Esel den Berg hinunterritt, kamen David und seine Männer ihr schon entgegen." },
      { number: 21, text: "David hatte eben noch gesagt: \"Für nichts und wieder nichts habe ich in der Wüste alles beschützt, was dem gehört. Nicht das Geringste von seinem Besitz ist weggekommen. Und er hat mir Gutes mit Bösem vergolten." },
      { number: 22, text: "So möge es Gott den Feinden Davids antun, so und noch mehr! Bis morgen früh werde ich nicht einen einzigen von diesen Wandpissern* übrig lassen!\"", footnotes: ["Wandpisser. Das ist ein bewusst verächtlicher Ausdruck für einen erwachsenen Mann."] },
      { number: 23, text: "Als Abigajil David sah, stieg sie schnell vom Esel, kniete sich hin und beugte sich mit dem Gesicht zur Erde nieder." },
      { number: 24, text: "Sie blieb vor seinen Füßen liegen und sagte: \"Es ist alles meine Schuld, mein Herr! Bitte hör deine Dienerin an, bitte lass es mich erklären!" },
      { number: 25, text: "Mein Herr ärgere sich doch nicht über Nabal, diesen boshaften Menschen. Er ist genau das, was sein Name bedeutet. Nabal* heißt er und niederträchtig ist er. Leider habe ich, deine Dienerin, die jungen Leute, die mein Herr geschickt hat, nicht gesehen.", footnotes: ["Nabal heißt Torheit und Niedertracht."] },
      { number: 26, text: "Nun aber, mein Herr, so wahr Jahwe lebt und du selbst lebst: Jahwe hat dich daran gehindert, in Blutschuld zu geraten, indem du dir mit eigener Hand hilfst. Mögen deine Feinde und alle, die dir schaden wollen, so wie Nabal werden!" },
      { number: 27, text: "Hier ist nun der Segensgruß, den deine Dienerin meinem Herrn brachte. Möge er an die Leute im Gefolge meines Herrn verteilt werden!" },
      { number: 28, text: "Vergib doch deiner Dienerin die Anmaßung! Ich weiß, dass Jahwe meinem Herrn ein beständiges Königshaus errichten wird, weil mein Herr die Kriege Jahwes führt. Dein Leben lang möge dir niemand ein Unrecht vorwerfen können." },
      { number: 29, text: "Und wenn dich jemand verfolgt, um dich umzubringen, soll das Leben meines Herrn bei denen verwahrt sein, die Jahwe, dein Gott, am Leben erhält! Aber das Leben deiner Feinde schleudere er mit der Schleuder weg!" },
      { number: 30, text: "Wenn dann Jahwe meinem Herrn all das Gute tun wird, das er dir zugesagt hat, und dich zum Fürsten über Israel bestellt," },
      { number: 31, text: "dann soll es dir, meinem Herrn, nicht zur Falle werden und nicht zum Vorwurf in deinem Gewissen führen, dass du ohne Grund Blut vergossen und dir selbst geholfen hast. Und wenn Jahwe meinem Herrn wohl tun wird, denk auch an deine Dienerin!\"" },
      { number: 32, text: "\"Gepriesen sei Jahwe, der Gott Israels\", rief David vor Abigajil, \"dass er dich mir heute entgegengeschickt hat!" },
      { number: 33, text: "Und gepriesen sei deine Klugheit! Gesegnet sollst du sein, dass du mich heute davor zurückgehalten hast, in Blutschuld zu geraten und mir selbst zu helfen!" },
      { number: 34, text: "Aber so wahr Jahwe, der Gott Israels, lebt, der mich davor bewahrt hat, dir Böses zu tun: Wenn du mir nicht so schnell entgegengekommen wärst, dann hätte Nabal bis zum Morgenlicht keinen seiner Wandpisser übrig behalten!\"" },
      { number: 35, text: "Dann nahm David die Gaben an, die sie ihm mitgebracht hatte, und sagte zu ihr: \"Geh in Frieden nach Hause! Ich habe auf dich gehört, und du kannst mir ins Gesicht schauen.\"" },
      { number: 36, text: "Als Abigajil nach Hause kam, saß Nabal mit seinen Leuten beim Festmahl; er feierte wie ein König, war gut gelaunt und völlig betrunken. Sie sagte ihm kein Wort von dem, was vorgefallen war." },
      { number: 37, text: "Erst am nächsten Morgen, als er wieder nüchtern war, erzählte seine Frau ihm alles. Da traf ihn der Schlag, und er war wie gelähmt." },
      { number: 38, text: "Zehn Tage später ließ Jahwe ihn sterben." },
      { number: 39, text: "Als David davon hörte, sagte er: \"Gepriesen sei Jahwe, der den Prozess gegen Nabals Unverschämtheit geführt und mich, seinen Diener, von einer bösen Tat abgehalten hat. Er hat Nabals Schlechtigkeit auf ihn selbst zurückfallen lassen.\" Dann schickte David Boten zu Abigajil und bat sie, seine Frau zu werden." },
      { number: 40, text: "Die Diener Davids kamen nach Karmel und sagten zu Abigajil: \"David schickt uns, er will dich zur Frau nehmen.\"" },
      { number: 41, text: "Da stand sie auf, kniete sich nieder, das Gesicht zur Erde, und sagte: \"Deine Dienerin ist bereit, den Dienern meines Herrn zu dienen und ihnen die Füße zu waschen.\"" },
      { number: 42, text: "Schnell machte sie sich reisefertig und setzte sich auf ihren Esel. Ihre fünf Mägde begleiteten sie. Sie folgte den Boten Davids und wurde seine Frau." },
      { number: 43, text: "David hatte bereits Ahinoam aus Jesreel* zur Frau genommen und war nun mit zwei Frauen verheiratet.", footnotes: ["Die Stadt Jesreel befindet sich mitten in der sehr fruchtbaren Jesreel-Ebene etwa 40 km nördlich von Samaria."] },
      { number: 44, text: "Davids Frau Michal, die Tochter Sauls, hatte Saul mit Palti Ben-Lajisch aus Gallim* verheiratet.", footnotes: ["Gallim war ein Dorf im Gebiet von Benjamin, 7-8 km nördlich von Jerusalem."] },
    ] },
    { number: 26, verses: [
      { number: 1, text: "Ein paar Männer aus Sif kamen erneut zu Saul nach Gibea und sagten: \"David hält sich auf dem Hügel Hachila gegenüber von Jeschimon versteckt.\"", heading: "David beschämt Saul zum zweiten Mal" },
      { number: 2, text: "Saul nahm 3000 der besten Männer Israels mit und machte sich auf den Weg in die Wüste Sif, um David dort zu suchen." },
      { number: 3, text: "Sie schlugen ihr Lager am Hügel Hachila auf, der gegenüber von Jeschimon liegt. David befand sich noch in der Wüste. Als er hörte, dass Saul wieder hinter ihm her war," },
      { number: 4, text: "schickte er Kundschafter aus und erfuhr mit Gewissheit, dass Saul gekommen war." },
      { number: 5, text: "Darauf erkundete David selbst den Lagerplatz Sauls. Er sah die Stelle, wo Saul sich neben Abner Ben-Ner, seinem Heerführer, zum Schlafen niedergelegt hatte. Saul lag im innersten Lagerring, seine Männer im Kreis um ihn herum." },
      { number: 6, text: "Mit David waren Ahimelech, der Hetiter, und Abischai, der Sohn der Zeruja und Bruder Joabs, gekommen. David fragte sie: \"Wer geht mit mir zu Saul ins Lager hinunter?\" – \"Ich komme mit\", sagte Abischai." },
      { number: 7, text: "In der Nacht schlichen David und Abischai ins Lager an den schlafenden Männern und an Abner vorbei. Sie fanden Saul im innersten Lagerring schlafend vor. An seinem Kopfende steckte der Speer in der Erde." },
      { number: 8, text: "Abischai flüsterte David zu: \"Heute hat Gott dir deinen Feind in die Hände gegeben! Ich will ihn mit dem Speer an den Boden spießen. Ich brauche nur einen Stoß dazu, keinen zweiten.\"" },
      { number: 9, text: "Aber David entgegnete ihm: \"Nein, bring ihn nicht um! Denn wer sich am Gesalbten Jahwes vergreift, wird nicht ungestraft bleiben.\"" },
      { number: 10, text: "Dann sagte David: \"So wahr Jahwe lebt: Sicher wird Jahwe ihn schlagen, wenn die Zeit gekommen ist, dass er sterben muss. Vielleicht kommt er auch in einem Krieg ums Leben." },
      { number: 11, text: "Jahwe bewahre mich davor, seinen Gesalbten anzutasten! Nimm jetzt den Speer an seinem Kopfende und seinen Wasserkrug – und dann lass uns hier verschwinden!\"" },
      { number: 12, text: "David nahm beides an sich, dann machten sie sich davon. Niemand sah etwas, niemand merkte etwas und niemand wachte auf, denn Jahwe hatte alle in einen tiefen Schlaf fallen lassen." },
      { number: 13, text: "David ging auf die andere Seite des Tals hinüber und stellte sich in sicherer Entfernung auf den Gipfel des Berges." },
      { number: 14, text: "Von dort aus rief er zum Kriegslager und zu Abner Ben-Ner hinüber: \"Abner, hörst du nicht?\" – \"Wer bist du, der da so zum König hin schreit?\", rief Abner zurück." },
      { number: 15, text: "Da sagte David: \"Du bist doch ein Mann, mit dem es keiner in Israel aufnehmen kann! Warum hast du deinen Herrn, den König, so schlecht bewacht? Vorhin ist jemand ins Lager eingedrungen, um deinen Herrn, den König, umzubringen." },
      { number: 16, text: "Das hast du nicht sehr gut gemacht! So wahr Jahwe lebt: Ihr habt den Tod verdient, weil ihr nicht über euren Herrn, den Gesalbten Jahwes, gewacht habt. Sieh doch einmal an seinem Kopfende nach, wo der Speer des Königs und sein Wasserkrug geblieben sind!\"" },
      { number: 17, text: "Da erkannte Saul die Stimme Davids und rief: \"Ist das nicht deine Stimme, mein Sohn David?\" – \"Es ist meine Stimme, mein Herr und König!\", erwiderte David" },
      { number: 18, text: "und fuhr fort: \"Warum jagt denn mein Herr seinem Diener nach? Was habe ich dir denn getan? Welches Unrecht habe ich begangen?" },
      { number: 19, text: "Nun hör doch auf die Worte deines Dieners, mein Herr und König! Wenn Jahwe dich gegen mich aufgebracht hat, so müssen wir ihn durch ein Opfer versöhnen. Wenn es aber Menschen sind, so sollen sie vor Jahwe verflucht sein! Denn sie lassen mich nicht am Erbe Jahwes teilhaben, als wollten sie sagen: 'Geh fort und diene fremden Göttern!'" },
      { number: 20, text: "Nein, mein Blut soll nicht fern von der Gegenwart Jahwes auf die Erde fließen, weil der König von Israel losgezogen ist, um einen einzelnen Floh zu fangen. Warum jagst du mich denn wie ein Rebhuhn* in den Bergen?\"", footnotes: ["Rebhuhn. Gemeint ist wohl das Arabische Wüstenhuhn."] },
      { number: 21, text: "Saul entgegnete: \"Ich habe versagt! Komm zurück, mein Sohn David! Ich werde dir nie mehr etwas Böses antun, weil du mein Leben heute so hoch geschätzt hast. Ich habe versagt und dir schweres Unrecht zugefügt.\"" },
      { number: 22, text: "David sagte darauf: \"Hier ist dein Speer, mein König! Einer von deinen Leuten soll herkommen und ihn holen!" },
      { number: 23, text: "Jahwe wird jedem seine Gerechtigkeit und Treue vergelten! Denn Jahwe hat dich heute in meine Hände gegeben, aber ich wollte mich nicht an seinem Gesalbten vergreifen." },
      { number: 24, text: "So wie dein Leben mir heute wertvoll war, so möge mein Leben Jahwe wertvoll sein, dass er mich aus aller Bedrängnis rettet.\"" },
      { number: 25, text: "Saul sagte: \"Gesegnet bist du, mein Sohn David! Alles, was du dir vornimmst, wird zustande kommen!\" David setzte seinen Weg fort, und Saul kehrte nach Hause zurück." },
    ] },
    { number: 27, verses: [
      { number: 1, text: "David dachte sich: \"Eines Tages werde ich doch noch von Saul umgebracht. Es bleibt mir nichts anderes übrig, als mich im Land der Philister in Sicherheit zu bringen. Dann wird Saul aufhören, mich im ganzen Gebiet Israels zu suchen. Dann bin ich vor ihm sicher.\"", heading: "David bei den Philistern" },
      { number: 2, text: "So zog David mit seinen 600 Mann zu Achisch Ben-Maoch, dem König von Gat." },
      { number: 3, text: "Er ließ sich mit seinen Männern bei ihm nieder. Jeder hatte seine Familie dabei. Auch Davids beide Frauen waren mitgekommen: Ahinoam aus Jesreel und Abigajil, die Witwe Nabals aus Karmel." },
      { number: 4, text: "Als Saul erfuhr, dass David nach Gat geflohen war, suchte er ihn nicht länger." },
      { number: 5, text: "Nun sagte David zu Achisch: \"Wenn ich deine Gunst gefunden habe, dann lass mich doch in eine deiner Städte auf dem Land ziehen. Warum soll dein Diener bei dir in der Königsstadt sitzen?\"" },
      { number: 6, text: "Darauf überließ ihm Achisch noch am selben Tag Ziklag. Das ist der Grund, warum Ziklag bis heute den Königen von Juda* gehört.", footnotes: ["heute ... Juda. Das meint den Zeitpunkt, als das Buch verfasst wurde und Israel schon in Nord- und Südreich geteilt war."] },
      { number: 7, text: "Ein Jahr und vier Monate lebte David im Gebiet der Philister." },
      { number: 8, text: "Von dort aus unternahm David mit seinen Männern Raubzüge gegen die Geschuriter*, die Girsiter* oder die Amalekiter, die von Alters her das Gebiet bis nach Schur* und an die Grenze Ägyptens bewohnten.", footnotes: ["Die hier erwähnten Geschuriter bewohnten ein Gebiet südlich des Philisterlandes und sind von dem Königreich Geschur (Josua 12,5) zu unterscheiden.", "Die Girsiter werden sonst im Alten Testament nicht erwähnt.", "Die Wüste Schur liegt zwischen dem \"Bach Ägyptens\" und dem heutigen Suez-Kanal. Der Ort Schur war eventuell das heutige Tell Fara, ein Vorposten der Ägypter."] },
      { number: 9, text: "Bei diesen Überfällen ließ David weder Mann noch Frau am Leben, aber die Schafe, Rinder, Esel, Kamele und auch die Kleidung nahm er als Beute mit." },
      { number: 10, text: "Wenn Achisch fragte: \"Wohin habt ihr heute den Streifzug gemacht?\", dann erwiderte David: \"In den Süden von Juda\", oder: \"In den Negev*, ins Gebiet der Jerachmeëliter!\", oder: \"Ins südliche Gebiet der Keniter!\"", footnotes: ["Negev. Das heiße Südland Israels, zum Teil gebirgige Wüste."] },
      { number: 11, text: "David ließ niemand am Leben und brachte auch keinen Gefangenen mit nach Gat, weil er verhindern wollte, dass sie gegen ihn aussagten. So machte David es während seiner ganzen Zeit bei den Philistern." },
      { number: 12, text: "Achisch glaubte David und dachte: \"Er hat sich bei seinem eigenen Volk, bei Israel, verhasst gemacht. Nun wird er für immer mein Diener sein.\"" },
    ] },
    { number: 28, verses: [
      { number: 1, text: "Damals zogen die Philister wieder ihre Truppen zusammen, um gegen Israel zu kämpfen. Achisch sagte zu David: \"Du bist dir doch im Klaren darüber, dass du mit deinen Männern auf unserer Seite in den Kampf ziehen musst.\"" },
      { number: 2, text: "\"Natürlich\", antwortete David, \"du wirst selbst sehen, was dein Diener leisten kann.\" – \"Gut\", sagte Achisch, \"ich mache dich zu meinem ständigen Leibwächter!\"" },
      { number: 3, text: "Samuel war gestorben und in seiner Heimatstadt Rama begraben worden. Ganz Israel hatte ihn betrauert. Die Totenbeschwörer und Wahrsager jedoch hatte Saul im ganzen Land beseitigt.", heading: "Saul sucht Rat bei einem Toten" },
      { number: 4, text: "Als die Philister ihre Truppen gesammelt hatten, schlugen sie ihr Lager bei Schunem* auf. Saul rief ganz Israel zusammen und ließ das Kriegslager auf den Bergen von Gilboa* aufschlagen.", footnotes: ["Schunem lag 15 km östlich von Megiddo am Fuß des Berges More. Heute: Solem.", "Gilboa bezeichnet eine Bergkette östlich der Ebene von Jesreel."] },
      { number: 5, text: "Als Saul das Heer der Philister sah, erschrak er und wurde ganz entmutigt." },
      { number: 6, text: "Er fragte Jahwe, doch Jahwe gab ihm keine Antwort, weder durch Träume noch durchs Los, noch durch einen Propheten." },
      { number: 7, text: "Da befahl Saul seinen Dienern: \"Sucht mir eine Totenbeschwörerin! Ich will zu ihr gehen und sie um Rat fragen!\" Seine Diener sagten: \"In En-Dor* lebt eine solche Frau.\"", footnotes: ["En-Dor lag etwa 10 km nordwestlich von Schunem und 5 km südlich vom Tabor. Heute: Endur."] },
      { number: 8, text: "Saul machte sein Gesicht unkenntlich, zog fremde Kleidung an und ging mit zwei Begleitern dorthin. Es war Nacht, als sie ankamen. \"Ich möchte, dass du mir durch den Geist eines Toten meine Zukunft voraussagst\", sagte er zu ihr. \"Lass den heraufkommen, den ich dir nennen werde!\"" },
      { number: 9, text: "Aber die Frau erwiderte: \"Du weißt doch selbst, dass Saul die Totenbeschwörer und Wahrsager im ganzen Land beseitigt hat. Warum stellst du mir eine Falle? Willst du mich töten?\"" },
      { number: 10, text: "Aber Saul schwor bei Jahwe: \"So wahr Jahwe lebt, in dieser Sache wird dich keine Strafe treffen!\"" },
      { number: 11, text: "\"Wen soll ich dir denn heraufkommen lassen?\", fragte die Frau. Saul erwiderte: \"Ruf Samuel!\"" },
      { number: 12, text: "Als die Frau dann wirklich Samuel sah, schrie sie auf und sagte zu Saul: \"Warum hast du mich betrogen? Du bist ja Saul!\"" },
      { number: 13, text: "\"Du hast nichts zu befürchten\", sagte der König zu ihr. \"Sag mir, was du siehst!\" – \"Ich sehe eine Art Gott aus der Erde heraufsteigen\", sagte sie." },
      { number: 14, text: "\"Wie sieht er aus?\", fragte er. \"Es ist ein alter Mann\", sagte sie. \"Er hat sich in einen Mantel gehüllt.\" Daran erkannte Saul, dass es Samuel war, und kniete sich nieder mit dem Gesicht zur Erde." },
      { number: 15, text: "\"Warum hast du meine Ruhe gestört und mich heraufkommen lassen?\", sagte Samuel. Saul erwiderte: \"Ich bin in großer Angst! Die Philister kämpfen gegen mich, und Gott hat mich verlassen. Er antwortet mir nicht mehr, weder durch Propheten noch durch Träume. Da ließ ich dich rufen, damit du mich wissen lässt, was ich tun soll.\"" },
      { number: 16, text: "Samuel sagte: \"Warum fragst du mich? Jahwe hat sich von dir abgewandt und ist dein Feind geworden." },
      { number: 17, text: "Er führt jetzt das aus, was er durch mich angekündigt hat: Er reißt das Königtum aus deiner Hand und gibt es David, deinem Nächsten." },
      { number: 18, text: "Weil du ihm nicht gehorcht hast, tut er dir das heute an. Du hast seinen glühenden Zorn an Amalek nicht vollstreckt." },
      { number: 19, text: "Jahwe wird das ganze Heer Israel zusammen mit dir in die Hände der Philister geben. Morgen wirst du mit deinen Söhnen bei mir sein.\"" },
      { number: 20, text: "Da stürzte Saul der Länge nach zu Boden. Die Worte Samuels hatten ihn zutiefst erschreckt. Es war auch keine Kraft mehr in ihm, weil er den ganzen Tag und die ganze Nacht nichts gegessen hatte." },
      { number: 21, text: "Die Frau eilte zu ihm. Als sie sah, dass er ganz verstört war, sagte sie: \"Deine Dienerin hat auf dich gehört. Ich habe mein Leben aufs Spiel gesetzt, als ich deine Bitte erfüllte." },
      { number: 22, text: "Nun hör doch auch auf mich! Ich werde dir eine Kleinigkeit zu essen bringen. Iss, damit du wieder zu Kräften kommst und deines Weges gehen kannst!\"" },
      { number: 23, text: "Aber er weigerte sich und sagte: \"Ich will nichts essen!\" Doch seine Diener und die Frau nötigten ihn, bis er auf sie hörte. Er stand auf und setzte sich aufs Bett." },
      { number: 24, text: "Die Frau hatte ein gemästetes Kalb im Stall. Das schlachtete sie jetzt in aller Eile. Dann nahm sie Mehl, machte einen Teig und backte ungesäuertes Fladenbrot." },
      { number: 25, text: "Das setzte sie Saul und seinen Dienern vor. Die aßen und gingen noch in derselben Nacht weg." },
    ] },
    { number: 29, verses: [
      { number: 1, text: "Die Philister sammelten ihre Heere bei Afek, und die Israeliten lagerten sich an der Quelle bei Jesreel.", heading: "David muss nicht gegen Israel kämpfen" },
      { number: 2, text: "Die Fürsten der Philister ließen ihre Truppen nach Hunderten und Tausenden an sich vorbeimarschieren. Mit Achisch zogen zuletzt auch David und seine Männer vorüber." },
      { number: 3, text: "Da fragten die Oberen der Philister: \"Was sollen diese Hebräer hier?\" Achisch erwiderte ihnen: \"Das ist doch David, der früher dem Israelitenkönig Saul gedient hat und nun schon seit Jahr und Tag bei mir ist. Seit er zu mir übergelaufen ist, hatte ich bis heute nicht das Geringste an ihm auszusetzen.\"" },
      { number: 4, text: "Doch die Oberen der Philister wurden zornig über ihn und sagten: \"Schick den Mann zurück! Er soll an dem Ort bleiben, den du ihm zugewiesen hast, und nicht mit uns in den Krieg ziehen, sonst wird er uns noch zum Gegner in der Schlacht. Denn womit könnte er die Gunst seines Herrn besser zurückgewinnen als mit den Köpfen dieser Männer!" },
      { number: 5, text: "Das ist doch derselbe David, von dem sie bei den Reigentänzen sangen:'Saul hat tausend Mann erschlagen, / David aber zehnmal tausend!'\"" },
      { number: 6, text: "Da rief Achisch David zu sich und sagte: \"So wahr Jahwe lebt, ja, du bist ein aufrichtiger Mann. Es wäre mir lieb gewesen, wenn du mit mir im Heer bleiben könntest. Denn seitdem du bei mir bist, habe ich nichts an dir auszusetzen. Aber die Fürsten trauen dir nicht." },
      { number: 7, text: "Kehr deshalb wieder um und geh in Frieden, damit du die Philisterfürsten nicht verärgerst.\"" },
      { number: 8, text: "David erwiderte ihm: \"Was habe ich denn getan? Hast du irgendetwas an mir auszusetzen, seit ich in deinen Dienst getreten bin? Weshalb soll ich nicht gegen die Feinde meines Herrn und Königs kämpfen?\"" },
      { number: 9, text: "Achisch erwiderte: \"Ich weiß es ja. Du bist mir so lieb wie ein Engel Gottes. Aber die Oberen der Philister haben nun einmal gesagt: 'Er darf nicht mit uns in den Kampf ziehen!'" },
      { number: 10, text: "Mach dich morgen früh auf und nimm alle mit, die früher einmal Saul gedient haben und mit dir gekommen sind! Zieht fort, sobald es hell wird!\"" },
      { number: 11, text: "So machte sich David bei Tagesanbruch auf den Weg und kehrte mit seinen Männern ins Land der Philister zurück. Die Philister aber zogen nach Jesreel hinauf." },
    ] },
    { number: 30, verses: [
      { number: 1, text: "Als David und seine Männer zwei Tage später in Ziklag ankamen, fanden sie die Stadt in Schutt und Asche gelegt. Die Amalekiter waren in den Negev eingefallen und hatten Ziklag verwüstet.", heading: "David vernichtet die Amalekiter" },
      { number: 2, text: "Sie hatten alle Frauen und Kinder in der Stadt als Gefangene verschleppt, aber niemand getötet." },
      { number: 3, text: "Als David und seine Männer die niedergebrannte Stadt sahen und feststellten, dass ihre Frauen und Kinder gefangen weggeschleppt worden waren," },
      { number: 4, text: "schrien sie laut auf und weinten, bis sie nicht mehr konnten." },
      { number: 5, text: "Auch die beiden Frauen Davids waren unter den Gefangenen: Ahinoam aus Jesreel und Abigajil, die Witwe Nabals aus Karmel." },
      { number: 6, text: "David kam in schwere Bedrängnis, denn die Leute sprachen davon, ihn zu steinigen, so erbittert waren sie über den Verlust ihrer Söhne und Töchter. Aber David holte sich Mut bei Jahwe, seinem Gott." },
      { number: 7, text: "Er befahl dem Priester Abjatar Ben-Ahimelech, das Efod zu bringen." },
      { number: 8, text: "Dann fragte er Jahwe: \"Soll ich diese Räuberbande verfolgen? Werde ich sie einholen?\" – \"Ja, verfolge sie! Du wirst sie gewiss einholen und die Gefangenen befreien!\", erhielt er zur Antwort." },
      { number: 9, text: "Da brach David mit seinen 600 Männern sofort auf. Als sie den Bach Besor* erreichten, machten die Zurückbleibenden dort Halt.", footnotes: ["Besor. Bachtal im Negev, südwestlich von Beerscheba."] },
      { number: 10, text: "200 Mann waren einfach zu erschöpft, um den Bach zu überqueren, und blieben zurück. David setzte die Verfolgung mit 400 Mann fort." },
      { number: 11, text: "Unterwegs fanden sie einen Ägypter und brachten ihn zu David. Sie gaben ihm Brot und Wasser." },
      { number: 12, text: "Dann reichten sie ihm eine Portion gepresste Feigen und zwei Rosinenkuchen. Als er gegessen hatte, kam er wieder zu Kräften und sagte, dass er drei Tage lang nichts zu essen und zu trinken gehabt hätte." },
      { number: 13, text: "David fragte ihn: \"Zu wem gehörst du und woher kommst du?\" – \"Ich bin ein Ägypter\", erwiderte er, \"der Sklave eines Amalekiters. Mein Herr hat mich vor drei Tagen hier zurückgelassen, weil ich krank wurde." },
      { number: 14, text: "Wir sind ins Südland der Kreter* eingefallen, in das südliche Gebiet Judas, wo die Nachkommen Kalebs wohnen, und haben auch Ziklag eingeäschert.\"", footnotes: ["Kreter. Das ist ein Hinweis darauf, dass die Philister ursprünglich von Kreta kamen."] },
      { number: 15, text: "\"Kannst du mich zu dieser Räuberbande hinführen?\", fragte David. Der Sklave erwiderte: \"Schwöre mir bei Gott, dass du mich nicht tötest oder meinem Herrn auslieferst! Dann werde ich dich zu dieser Bande hinunterführen.\"" },
      { number: 16, text: "Er führte sie hin, und sie fanden die Amalekiter über die ganze Gegend zerstreut. Sie aßen und tranken und tanzten, weil sie bei den Philistern und in Juda so reiche Beute gemacht hatten." },
      { number: 17, text: "David fiel über sie her und schlug sie von der Morgendämmerung an bis zum Abend des folgenden Tages. Alle wurden niedergemacht, nur 400 junge Männer konnten auf Kamelen fliehen." },
      { number: 18, text: "David befreite alle Gefangenen und auch seine beiden Frauen." },
      { number: 19, text: "Niemand wurde vermisst, weder Söhne noch Töchter, noch irgendwelche Beute. Alles, was die Amalekiter weggenommen hatten, brachte David zurück." },
      { number: 20, text: "Die Schafe, Ziegen und Rinder der Amalekiter nahm David für sich. Seine Leute trieben sie vor ihrem eigenen Vieh her und sagten: \"Das ist Davids Beute!\"" },
      { number: 21, text: "Die 200 Männer, die zu erschöpft gewesen waren, um David zu folgen, und am Besorbach zurückgeblieben waren, kamen nun David und seinen Männern entgegen. David ging auf sie zu und fragte sie nach ihrem Wohlergehen." },
      { number: 22, text: "Aber unter denen, die mit David gezogen waren, gab es ein paar bösartige und niederträchtige Männer, die sagten: \"Sie sind nicht mit uns in den Kampf gezogen, also geben wir ihnen auch nichts von der Beute, die wir gemacht haben. Sie sollen ihre Frauen und Kinder nehmen und verschwinden.\"" },
      { number: 23, text: "Doch David sagte: \"Nein, meine Brüder, so machen wir es nicht mit dem, was Jahwe uns schenkte! Er war es doch, der uns beschützt und diese Räuberbande in unsere Hände gegeben hat." },
      { number: 24, text: "Wer sollte denn in dieser Sache auf euch hören? Nein, der eine zieht in den Kampf, der andere schützt den Tross, und die Beute wird ehrlich unter alle geteilt!\"" },
      { number: 25, text: "Von da an wurde es immer so gehandhabt. David machte es zu einem festen Recht in Israel, und es wird bis heute befolgt." },
      { number: 26, text: "Als David dann nach Ziklag zurückkam, schickte er einen Teil der Beute an die Ältesten Judas, seine Nachbarn, und ließ ihnen ausrichten: \"Hier ist ein Segensgruß aus der Beute der Feinde Jahwes für euch!\"" },
      { number: 27, text: "Er schickte solche Geschenke nach Betuël, nach Ramot im Negev, nach Jattir," },
      { number: 28, text: "Aroer, Sifmot, Eschtemoa" },
      { number: 29, text: "und Rakal, in die Städte der Jerachmeëliter und Keniter," },
      { number: 30, text: "nach Horma, Bor-Aschan, Atach" },
      { number: 31, text: "und Hebron, und außerdem in alle Orte, in denen er sich mit seinen Leuten aufgehalten hatte." },
    ] },
    { number: 31, verses: [
      { number: 1, text: "Zwischen den Philistern und Israel kam es zur Schlacht. Die Männer Israels mussten vor den Philistern fliehen und viele von ihnen blieben erschlagen auf den Bergen von Gilboa liegen.", heading: "Sauls Ende" },
      { number: 2, text: "Die Philister holten schließlich auch Saul und seine Söhne ein. Sie erschlugen die drei Söhne Sauls Jonatan, Abinadab und Malkischua." },
      { number: 3, text: "Um Saul herum tobte ein erbitterter Kampf. Die Bogenschützen hatten ihn getroffen und schwer verwundet." },
      { number: 4, text: "Da sagte Saul zu seinem Waffenträger: \"Zieh dein Schwert und töte mich, damit nicht diese Unbeschnittenen es tun und ihren Spott mit mir treiben!\" Sein Waffenträger aber wollte es nicht tun, er scheute sich davor. Da nahm Saul sein Schwert und stürzte sich hinein." },
      { number: 5, text: "Als der Waffenträger sah, dass Saul tot war, stürzte auch er sich in sein Schwert und starb neben ihm." },
      { number: 6, text: "So starben Saul, seine drei Söhne, sein Waffenträger und alle seine Männer an diesem einen Tag." },
      { number: 7, text: "Als die Israeliten der Jesreel-Ebene und der umliegenden Gegenden sahen, dass die Männer Israels geflohen und Saul und seine Söhne tot waren, verließen sie ihre Städte und flohen. Die Philister nahmen sie in Besitz und wohnten darin." },
      { number: 8, text: "Am Tag nach der Schlacht kamen die Philister, um die Gefallenen zu plündern. Dabei fanden sie Saul und seine drei Söhne auf den Bergen von Gilboa." },
      { number: 9, text: "Sie hieben Saul den Kopf ab und zogen ihm seine Rüstung aus. Beides ließen sie im Land der Philister herumzeigen, um die Freudenbotschaft in ihren Götzentempeln und unter dem Volk zu verkünden." },
      { number: 10, text: "Seine Rüstung legten sie in den Tempel der Astarte und seine Leiche hefteten sie an die Mauer von Bet-Schean*.", footnotes: ["Bet-Schean lag 24 km südlich vom See Gennesaret in der Ebene Jesreel und war eine Festung der Philister."] },
      { number: 11, text: "Als die Bewohner von Jabesch in Gilead* hörten, was die Philister Saul angetan hatten,", footnotes: ["Jabesch in Gilead lag 15 km südöstlich von Bet-Schean im Ostjordanland."] },
      { number: 12, text: "machten sich alle wehrfähigen Männer auf, marschierten die ganze Nacht hindurch und nahmen die Leichen Sauls und auch die seiner Söhne von der Mauer von Bet-Schean ab. Sie brachten sie nach Jabesch und verbrannten sie dort." },
      { number: 13, text: "Ihre Gebeine begruben sie unter der Tamariske von Jabesch und fasteten sieben Tage lang." },
    ] },
  ],
};